window.QB_TKP_B12 = [
{id:"TKP-1801", q:"Anda bertugas di loket pelayanan KTP kecamatan. Seorang warga datang marah-marah karena KTP-nya belum jadi setelah 3 minggu, padahal ia butuh untuk melamar kerja besok. Sikap yang paling tepat adalah ....", opts:[{t:"Mendengarkan keluhannya dengan tenang, mengecek status pencetakan, menjelaskan kendala blanko secara jujur, dan memberi surat keterangan pengganti sementara", s:5},{t:"Meminta maaf atas keterlambatan dan berjanji memprioritaskan pencetakannya minggu ini", s:4},{t:"Menjelaskan bahwa keterlambatan karena blanko dari pusat dan memintanya menunggu", s:3},{t:"Menyuruhnya kembali minggu depan tanpa mengecek statusnya", s:2},{t:"Membentaknya balik karena bersikap tidak sopan kepada petugas", s:1}], ex:"Mendengarkan, transparan soal kendala, dan memberi solusi sementara adalah pelayanan prima; membentak warga melanggar etika pelayanan publik."},
{id:"TKP-1802", q:"Anda bekerja di bagian informasi puskesmas. Seorang lansia bernama Slamet bingung mengisi formulir pendaftaran online karena tidak punya ponsel pintar. Tindakan yang paling tepat adalah ....", opts:[{t:"Menyuruhnya pulang dan meminta anaknya mendaftarkan dari rumah", s:2},{t:"Menjelaskan bahwa pendaftaran kini wajib online sehingga ia harus belajar", s:3},{t:"Membantunya mendaftar secara manual sambil mengajari langkah dasar penggunaan aplikasi", s:5},{t:"Menawarkan bantuan pendaftaran manual tanpa mengajarinya apa-apa", s:4},{t:"Memintanya membayar biaya tambahan agar dibantu mengisi formulir", s:1}], ex:"Membantu langsung sekaligus memberdayakan warga agar mandiri di kemudian hari mencerminkan empati dan inklusivitas pelayanan publik."},
{id:"TKP-1803", q:"Di grup WhatsApp warga, beredar pesan berantai yang mengklaim dinas tempat Anda bekerja menarik pungutan liar untuk pengurusan surat domisili. Anda adalah admin komunikasi dinas. Respon paling tepat adalah ....", opts:[{t:"Mengabaikan pesan tersebut karena bukan tugas Anda memantau grup warga", s:2},{t:"Meminta warga menghapus pesan itu agar tidak menimbulkan keributan", s:3},{t:"Melaporkan pembuat pesan ke polisi tanpa klarifikasi lebih dulu", s:1},{t:"Menindaklanjuti dengan klarifikasi resmi bahwa tidak ada pungutan, disertai nomor pengaduan resmi", s:5},{t:"Menjawab singkat bahwa info itu tidak benar tanpa bukti pendukung", s:4}], ex:"Klarifikasi resmi yang cepat dan dilengkapi kanal pengaduan adalah bentuk akuntabilitas dan tanggung jawab melawan hoaks yang menyerang citra instansi."},
{id:"TKP-1804", q:"Anda melayani antrean panjang di kantor dukcapil. Seorang ibu hamil tua datang dan terlihat kelelahan berdiri. Sementara antrean sudah tertib bernomor. Sikap paling tepat adalah ....", opts:[{t:"Tetap menyuruhnya antre karena semua warga harus diperlakukan sama", s:2},{t:"Memintanya duduk di kursi tunggu tapi tetap sesuai nomor antrean", s:4},{t:"Memprioritaskannya ke loket prioritas untuk kelompok rentan sesuai aturan pelayanan", s:5},{t:"Menegur warga lain yang keberatan agar tidak protes", s:3},{t:"Membiarkannya berdiri karena takut dituduh pilih kasih oleh warga lain", s:1}], ex:"Mengutamakan kelompok rentan adalah prinsip keadilan substantif dalam pelayanan publik, bukan pilih kasih."},
{id:"TKP-1805", q:"Seorang warga bernama Rina menelepon pengaduan karena namanya tercantum di situs layanan daring dinas dengan nomor KTP lengkap yang bisa dilihat siapa saja. Sebagai petugas data, tindakan paling tepat adalah ....", opts:[{t:"Menjelaskan bahwa data diunggah otomatis oleh sistem dan tidak bisa diubah", s:2},{t:"Meminta maaf, segera menyamarkan data pribadi tersebut, dan melaporkan celah ke tim keamanan", s:5},{t:"Menyarankan agar Rina mengganti nomor KTP-nya saja", s:1},{t:"Berjanji akan menindaklanjuti minggu depan setelah rapat", s:3},{t:"Menyamarkan data tersebut tanpa memberitahu Rina atau atasan", s:4}], ex:"Perlindungan data pribadi warga adalah kewajiban hukum; respon cepat, transparan, dan dilaporkan mencerminkan akuntabilitas."},
{id:"TKP-1806", q:"Anda petugas di dinas perizinan. Seorang pengusaha menawarkan amplop berisi uang agar izin usahanya diterbitkan hari ini juga, padahal berkasnya belum lengkap. Sikap paling tepat adalah ....", opts:[{t:"Menolak dengan tegas, menjelaskan syarat yang kurang, dan mencatat upaya suap dalam laporan", s:5},{t:"Menolak amplopnya tapi tetap mempercepat prosesnya secara diam-diam", s:2},{t:"Menerima amplop lalu memproses izinnya seperti biasa", s:1},{t:"Menolak amplop dan memintanya melengkapi berkas tanpa penjelasan lebih lanjut", s:4},{t:"Meneruskan tawaran tersebut ke atasan agar atasan yang memutuskan", s:3}], ex:"Menolak gratifikasi dan mendokumentasikannya adalah wujud integritas ASN; integritas tidak bisa ditawar dengan dalih mempercepat layanan."},
{id:"TKP-1807", q:"Anda mengelola akun media sosial resmi kelurahan. Seorang warga berkomentar kasar menuduh lurah korupsi karena jalan di gangnya belum diperbaiki. Respon paling tepat adalah ....", opts:[{t:"Menghapus komentarnya dan memblokir akunnya agar tidak merusak citra", s:1},{t:"Membalas dengan nada emosional membela lurah", s:2},{t:"Menjawab dengan sopan, menjelaskan status rencana perbaikan jalan, dan mengajak melapor via kanal resmi", s:5},{t:"Mengabaikan komentar tersebut karena sifatnya provokatif", s:3},{t:"Membalas singkat bahwa keluhan sudah diterima tanpa penjelasan statusnya", s:4}], ex:"Menjawab kritik warga dengan sopan, transparan soal progres, dan mengarahkan ke kanal resmi adalah komunikasi publik yang profesional."},
{id:"TKP-1808", q:"Di loket imigrasi, paspor seorang warga bernama Hendra ditolak sistem karena datanya ganda, padahal ia harus berangkat umrah tiga hari lagi. Ia memohon dibantu. Sikap paling tepat adalah ....", opts:[{t:"Menjelaskan masalah data ganda dan menyuruhnya kembali setelah diperbaiki entah kapan", s:2},{t:"Meminta ia membayar biaya percepatan agar datanya segera dibereskan", s:1},{t:"Mengecek akar masalah, menjelaskan prosedurnya dengan jujur, dan mengupayakan percepatan sesuai aturan", s:5},{t:"Melaporkannya ke atasan lalu menunggu instruksi tanpa bertindak", s:3},{t:"Membantu memeriksa datanya dan memberi perkiraan waktu tanpa janji yang jelas", s:4}], ex:"Solusi konkret yang tetap dalam koridor aturan plus komunikasi jujur soal waktu adalah pelayanan prima dalam situasi mendesak."},
{id:"TKP-1809", q:"Anda menerima pesan WhatsApp dari nomor tak dikenal yang mengaku atasan Anda dan meminta data NIK warga untuk keperluan verifikasi. Tindakan paling tepat adalah ....", opts:[{t:"Mengirimkan data karena pengirim mengaku atasan dan terlihat mendesak", s:1},{t:"Menanyakan dulu keperluan detailnya sebelum mengirim sebagian data", s:2},{t:"Mengabaikan pesan dan tidak melaporkannya ke siapa pun", s:3},{t:"Memverifikasi melalui kanal resmi (telepon kantor), tidak mengirim data, dan melaporkan dugaan penipuan", s:5},{t:"Menolak mengirim tapi tidak memverifikasi karena takut menyinggung atasan", s:4}], ex:"Data NIK warga adalah data pribadi yang dilindungi; verifikasi identitas peminta via kanal resmi adalah kehati-hatian yang wajib."},
{id:"TKP-1810", q:"Antrean di kantor pajak membludak karena sistem antrean digital error. Warga mulai ribut dan saling serobot. Sebagai petugas, langkah paling tepat adalah ....", opts:[{t:"Membiarkan warga mengatur sendiri antreannya agar tidak disalahkan", s:2},{t:"Menutup loket sementara sampai sistem pulih tanpa penjelasan", s:1},{t:"Mengumumkan maaf atas gangguan, beralih ke antrean manual bernomor, dan menambah petugas", s:5},{t:"Meminta warga menunggu dengan sabar sampai sistem pulih", s:3},{t:"Membuka loket dengan sistem siapa cepat dia dapat agar antrean cepat habis", s:4}], ex:"Mengambil alih situasi dengan solusi manual yang tertib plus komunikasi terbuka menunjukkan kepemimpinan pelayanan saat krisis."},
{id:"TKP-1811", q:"Seorang warga disabilitas netra bernama Fajar datang ke kelurahan untuk mengurus surat keterangan tidak mampu. Formulirnya panjang dan rumit. Sikap paling tepat adalah ....", opts:[{t:"Memintanya membawa pendamping lain kali karena petugas sibuk", s:2},{t:"Menyerahkan formulir dan memintanya mengisi sendiri semampunya", s:1},{t:"Membacakan dan membantu mengisi formulir dengan sabar hingga selesai", s:5},{t:"Menjelaskan isi formulir secara umum lalu memintanya menandatangani", s:3},{t:"Membantu mengisi formulir tanpa menjelaskan isinya agar cepat selesai", s:4}], ex:"Pelayanan inklusif berarti memastikan warga disabilitas benar-benar memahami dan terlayani, bukan sekadar diselesaikan administrasinya."},
{id:"TKP-1812", q:"Anda menemukan rekan kerja mengunggah foto KTP seorang warga ke status WhatsApp-nya dengan caption lucu-lucuan. Sebagai sesama ASN, tindakan paling tepat adalah ....", opts:[{t:"Membiarkannya karena bukan urusan Anda dan takut merusak hubungan kerja", s:2},{t:"Ikut menertawakan karena fotonya memang lucu", s:1},{t:"Menegur rekan secara pribadi, memintanya menghapus, dan mengingatkan soal perlindungan data pribadi", s:5},{t:"Melaporkannya langsung ke atasan tanpa menegur lebih dulu", s:3},{t:"Mengingatkannya agar lain kali tidak mengunggah, tanpa memintanya menghapus", s:4}], ex:"Menegur langsung dan meminta penghapusan melindungi warga sekaligus menegakkan etika; eskalasi bisa menyusul bila diabaikan."},
{id:"TKP-1813", q:"Aplikasi layanan perizinan daring daerah Anda sering down saat jam sibuk. Banyak warga mengeluh di media sosial. Sebagai bagian tim layanan, usulan paling tepat yang Anda sampaikan adalah ....", opts:[{t:"Menyarankan agar warga datang langsung saja ke kantor seperti dulu", s:2},{t:"Mengusulkan perbaikan kapasitas server, status layanan real-time, dan kanal antrean cadangan", s:5},{t:"Mengusulkan pengumuman maaf di media sosial tanpa perbaikan teknis", s:3},{t:"Mengusulkan penambahan jam operasional loket fisik untuk menampung keluhan", s:4},{t:"Mengusulkan agar kolom komentar media sosial dimatikan agar keluhan berhenti", s:1}], ex:"Solusi sistemik (kapasitas, transparansi status, cadangan) menyelesaikan akar masalah, bukan menutupi keluhan warga."},
{id:"TKP-1814", q:"Seorang ibu bernama Dewi menangis di loket RSUD karena ditolak berobat dengan alasan kartu BPJS-nya nonaktif, padahal anaknya demam tinggi. Sikap paling tepat adalah ....", opts:[{t:"Tetap menolak sesuai prosedur karena kartu memang nonaktif", s:2},{t:"Menyuruhnya mengaktifkan BPJS dulu di kantor BPJS hari itu juga", s:3},{t:"Mengarahkan ke IGD untuk penanganan darurat sambil membantu koordinasi pengaktifan kartu", s:5},{t:"Mengizinkannya berobat dengan membayar umum tanpa menjelaskan opsi lain", s:4},{t:"Memintanya pulang dan kembali setelah kartu aktif", s:1}], ex:"Keselamatan pasien darurat didahulukan; membantu mengurus administrasi paralel adalah empati yang tetap prosedural."},
{id:"TKP-1815", q:"Anda bertugas di bagian pengaduan dinas. Seorang warga melapor bahwa namanya dicatut untuk pengajuan bantuan sosial oleh oknum RT. Tindak lanjut paling tepat adalah ....", opts:[{t:"Menyuruh warga menyelesaikan sendiri dengan RT-nya karena urusan internal lingkungan", s:2},{t:"Mencatat laporan, memverifikasi data penerima bansos, dan meneruskan ke tim verifikasi serta aparat bila terindikasi pidana", s:5},{t:"Langsung menuduh oknum RT bersalah di depan warga", s:1},{t:"Mencatat laporan dan berjanji menindaklanjuti tanpa batas waktu jelas", s:3},{t:"Mengganti nama warga dengan penerima lain agar masalah cepat selesai", s:4}], ex:"Verifikasi faktual dan jalur tindak lanjut yang jelas melindungi hak warga sekaligus menjaga asas praduga tak bersalah."},
{id:"TKP-1816", q:"Warga bernama Agus mengeluh via aplikasi lapor bahwa petugas loket kecamatan bermain ponsel saat melayaninya. Anda adalah atasan petugas tersebut. Respon paling tepat adalah ....", opts:[{t:"Mengabaikan laporan karena hanya masalah sepele soal ponsel", s:2},{t:"Langsung memberi sanksi berat kepada petugas tanpa klarifikasi", s:1},{t:"Memverifikasi kejadian, menegur dan membina petugas, serta menyampaikan hasil tindak lanjut ke pelapor", s:5},{t:"Meminta petugas meminta maaf kepada warga tanpa pembinaan lanjutan", s:3},{t:"Menegur petugas secara lisan tanpa menindaklanjuti laporan warga", s:4}], ex:"Menutup loop pengaduan (verifikasi, pembinaan, umpan balik ke warga) adalah akuntabilitas pelayanan yang utuh."},
{id:"TKP-1817", q:"Anda petugas arsip digital dukcapil. Seorang wartawan meminta daftar lengkap NIK dan alamat warga untuk bahan liputan. Sikap paling tepat adalah ....", opts:[{t:"Memberikannya karena wartawan butuh untuk kepentingan publik", s:1},{t:"Memberikan sebagian data saja agar liputannya tetap jalan", s:2},{t:"Menolak dan menjelaskan bahwa data pribadi warga dilindungi undang-undang", s:5},{t:"Memintanya mengajukan surat resmi dulu baru data diberikan", s:3},{t:"Menolak tapi tidak menjelaskan alasannya agar tidak berdebat", s:4}], ex:"Menolak tegas dengan dasar hukum melindungi data pribadi; kepentingan publik tidak membenarkan pembukaan data personal."},
{id:"TKP-1818", q:"Di sekolah tempat Anda menjadi tata usaha, seorang wali murid bernama Maya protes karena anaknya tidak lolos seleksi beasiswa padahal nilainya bagus. Ia menuduh panitia tidak adil. Sikap paling tepat adalah ....", opts:[{t:"Membela panitia dan menyuruhnya menerima hasil seleksi", s:2},{t:"Menunjukkan kriteria dan rekap nilai secara transparan serta menjelaskan mekanisme sanggah", s:5},{t:"Menjanjikan akan memasukkan anaknya ke daftar penerima tahun depan", s:1},{t:"Memintanya mengajukan protes tertulis tanpa menjelaskan kriterianya", s:3},{t:"Menjelaskan kriteria secara umum tanpa menunjukkan data", s:4}], ex:"Transparansi kriteria dan mekanisme sanggah yang jelas adalah cara adil menjawab tuduhan ketidakadilan."},
{id:"TKP-1819", q:"Anda menerima email berisi tautan yang mengaku dari portal kepegawaian dan meminta Anda login untuk verifikasi data. Tautan terlihat mencurigakan. Tindakan paling tepat adalah ....", opts:[{t:"Mengklik tautan karena khawatir data kepegawaian bermasalah", s:1},{t:"Mengabaikan email dan tidak melaporkannya", s:3},{t:"Meneruskan email ke rekan agar mereka waspada", s:2},{t:"Tidak mengklik, memverifikasi lewat situs resmi yang diketik manual, dan melaporkan ke tim keamanan siber", s:5},{t:"Menghapus email tanpa verifikasi apa pun", s:4}], ex:"Tidak mengklik phising, verifikasi mandiri via kanal resmi, dan melapor melindungi data pribadi ASN dan sistem instansi."},
{id:"TKP-1820", q:"Seorang warga lanjut usia bernama Nur datang ke dinas sosial menanyakan bantuan yang dijanjikan tapi tak kunjung cair. Ia tidak paham istilah administrasi yang Anda jelaskan. Sikap paling tepat adalah ....", opts:[{t:"Menjelaskan ulang dengan bahasa sederhana, mengecek status bantuannya, dan memberi tahu langkah berikutnya", s:5},{t:"Mengulang penjelasan yang sama dengan suara lebih keras", s:2},{t:"Memintanya kembali dengan anaknya yang lebih paham", s:3},{t:"Memberi brosur syarat bantuan agar dibaca di rumah", s:4},{t:"Menyuruhnya menunggu karena pencairan memang butuh waktu lama", s:1}], ex:"Komunikasi yang disesuaikan dengan kemampuan warga plus pengecekan status nyata adalah pelayanan yang manusiawi."},
{id:"TKP-1821", q:"Anda melihat antrean loket pembayaran PBB sangat panjang dan banyak warga lanjut usia kepanasan di luar. Padahal ada ruangan tunggu ber-AC yang kosong. Keputusan paling tepat adalah ....", opts:[{t:"Membiarkan antrean seperti biasa karena sudah prosedurnya", s:2},{t:"Mempersilakan warga menunggu di ruangan ber-AC dengan sistem pemanggilan nomor yang tertib", s:5},{t:"Membuka loket tambahan tanpa mengatur ulang antrean", s:4},{t:"Meminta warga bersabar karena petugas terbatas", s:3},{t:"Menyuruh warga pulang dan membayar lewat aplikasi saja", s:1}], ex:"Memanfaatkan fasilitas yang ada demi kenyamanan warga, dengan ketertiban antrean tetap dijaga, adalah inisiatif pelayanan."},
{id:"TKP-1822", q:"Seorang warga memvideokan Anda saat melayani dan mengunggahnya ke media sosial dengan caption yang memelintir kejadian. Video itu viral dan Anda dibully warganet. Sikap paling tepat adalah ....", opts:[{t:"Membalas setiap komentar jahat untuk membersihkan nama baik", s:2},{t:"Melaporkan semua akun yang membully ke polisi", s:1},{t:"Tetap tenang, mengumpulkan bukti kronologi, dan meminta humas instansi memberikan klarifikasi resmi", s:5},{t:"Menghapus akun media sosial pribadi agar tidak ditemukan", s:3},{t:"Meminta warga yang mengunggah menghapus videonya secara baik-baik", s:4}], ex:"Tetap profesional, dokumentasikan fakta, dan serahkan klarifikasi ke humas resmi agar tidak memperkeruh keadaan."},
{id:"TKP-1823", q:"Anda petugas pendaftaran di puskesmas. Sistem antrean online menunjukkan kuota dokter habis, tetapi seorang pasien bernama Dedi datang jauh-jauh dari desa dan memohon tetap diperiksa. Sikap paling tepat adalah ....", opts:[{t:"Menolaknya mentah-mentah karena kuota sudah habis sesuai sistem", s:1},{t:"Menyuruhnya mendaftar online untuk besok tanpa solusi hari ini", s:2},{t:"Mengarahkannya ke poli umum atau menjadwalkan ulang dengan prioritas, sambil menjelaskan dengan empati", s:5},{t:"Menyelipkannya diam-diam ke antrean dokter tanpa sepengetahuan perawat", s:4},{t:"Memintanya menunggu siapa tahu ada pasien yang batal", s:3}], ex:"Menawarkan alternatif layanan yang sah sambil menghargai pengorbanan jarak tempuhnya adalah empati yang tetap tertib aturan."},
{id:"TKP-1824", q:"Di grup WhatsApp RT, tersebar foto surat resmi dinas Anda yang belum dipublikasikan, lengkap dengan tanda tangan kepala dinas. Anda mengenali dokumen itu dari meja kerja Anda. Tindakan paling tepat adalah ....", opts:[{t:"Membiarkannya karena dokumen itu akhirnya akan dipublikasikan juga", s:2},{t:"Menghapus pesan di grup karena Anda juga anggota grup", s:3},{t:"Menuduh rekan kerja sebagai pembocor di grup tersebut", s:1},{t:"Melaporkan kebocoran ke atasan, meminta klarifikasi resmi, dan mengevaluasi pengamanan dokumen", s:5},{t:"Meminta admin grup menghapus foto tanpa melapor ke atasan", s:4}], ex:"Kebocoran dokumen dinas adalah masalah keamanan informasi; dilaporkan resmi dan dievaluasi, bukan ditutupi."},
{id:"TKP-1825", q:"Seorang warga bernama Putri ingin mengurus surat pindah domisili tetapi KTP aslinya hilang. Ia hanya membawa fotokopi dan surat kehilangan dari polisi. Sikap paling tepat adalah ....", opts:[{t:"Menolak karena syarat mutlak harus KTP asli", s:1},{t:"Memintanya mengurus KTP baru dulu baru kembali mengurus surat pindah", s:2},{t:"Menerima surat kehilangan sebagai pengganti sah, memverifikasi datanya, dan memproses surat pindah", s:5},{t:"Meneruskan ke atasan agar atasan yang memutuskan", s:3},{t:"Memprosesnya tetapi memintanya kembali lagi membawa KTP asli nanti", s:4}], ex:"Surat kehilangan dari kepolisian adalah dokumen sah pengganti; menolaknya adalah mempersulit warga tanpa dasar."},
{id:"TKP-1826", q:"Anda ditugaskan membuat konten edukasi anti-hoaks untuk media sosial dinas. Topik yang sedang ramai adalah hoaks lowongan CPNS berbayar. Pendekatan paling tepat adalah ....", opts:[{t:"Membuat konten yang menakut-nakuti warga agar tidak tertipu", s:2},{t:"Mengabaikan karena hoaks CPNS bukan wewenang dinas Anda", s:3},{t:"Membuat infografis ciri hoaks, kanal resmi informasi, dan ajakan verifikasi sebelum membayar apa pun", s:5},{t:"Memposting ulang peringatan dari akun lain tanpa adaptasi", s:4},{t:"Menulis konten menyindir para korban penipuan agar jera", s:1}], ex:"Edukasi yang memberdayakan (ciri hoaks + kanal resmi + ajakan verifikasi) mencegah korban baru, bukan menyalahkan korban lama."},
{id:"TKP-1827", q:"Warga bernama Joko komplain karena petugas loket memberikan informasi berbeda-beda soal syarat perpanjangan SIM keliling. Ia sudah dua kali bolak-balik. Sikap paling tepat adalah ....", opts:[{t:"Menyalahkan petugas yang memberi info salah di depan warga", s:1},{t:"Meminta maaf, memberikan informasi yang benar dan tertulis, serta memastikan ia tidak perlu bolak-balik lagi", s:5},{t:"Menjelaskan syarat yang benar tanpa meminta maaf atas kesalahan sebelumnya", s:4},{t:"Memintanya bertanya langsung ke petugas yang kemarin memberinya info", s:2},{t:"Menyuruhnya membaca papan informasi yang sudah terpampang", s:3}], ex:"Meminta maaf atas kesalahan instansi, memberi info benar tertulis, dan menutup masalahnya tuntas adalah service recovery yang baik."},
{id:"TKP-1828", q:"Anda petugas di kantor pajak. Seorang wajib pajak lansia tidak bisa menggunakan aplikasi pelaporan online dan takut didenda. Sikap paling tepat adalah ....", opts:[{t:"Menyuruhnya membayar denda saja karena memang kewajibannya", s:1},{t:"Menjelaskan bahwa semua kini online dan ia harus minta tolong keluarga", s:2},{t:"Membantunya melaporkan secara langsung, mengajari langkah dasar, dan menjelaskan cara menghindari denda", s:5},{t:"Mengarahkannya ke loket manual tanpa pendampingan", s:4},{t:"Memintanya datang lain hari saat petugas lebih longgar", s:3}], ex:"Pendampingan langsung plus edukasi mencegah denda yang tidak perlu; transformasi digital tidak boleh meninggalkan warga rentan."},
{id:"TKP-1829", q:"Seorang rekan kerja meminta Anda membocorkan jadwal sidak pimpinan ke pedagang pasar agar mereka siap-siap. Ia berdalih demi menjaga hubungan baik. Sikap paling tepat adalah ....", opts:[{t:"Memberitahunya karena hanya jadwal, bukan rahasia negara", s:2},{t:"Menolak dan mengingatkan bahwa membocorkan operasi merusak tujuan pengawasan", s:5},{t:"Memberi tahu secara samar tanpa detail waktu", s:3},{t:"Melaporkannya ke pimpinan tanpa menegur lebih dulu", s:4},{t:"Menyetujuinya demi menjaga hubungan baik dengan rekan", s:1}], ex:"Menolak tegas karena sidak yang bocor kehilangan makna; integritas pengawasan lebih penting dari relasi sesaat."},
{id:"TKP-1830", q:"Anda mengelola aplikasi pengaduan daerah. Ada laporan masuk berisi ujaran kebencian terhadap suku tertentu yang dikemas sebagai keluhan pelayanan. Tindakan paling tepat adalah ....", opts:[{t:"Meneruskan laporan apa adanya karena semua laporan warga harus diproses", s:2},{t:"Menghapus laporan dan memblokir pelapor tanpa penjelasan", s:1},{t:"Menolak memproses muatan ujaran kebencian, menjelaskan batasannya, dan tetap menindaklanjuti inti keluhan pelayanannya bila ada", s:5},{t:"Mengabaikan laporan tersebut sepenuhnya", s:3},{t:"Memproses keluhannya sambil membiarkan ujaran kebenciannya", s:4}], ex:"Kanal pengaduan tidak boleh menjadi corong ujaran kebencian; inti layanan tetap ditindaklanjuti secara proporsional."},
{id:"TKP-1831", q:"Warga bernama Ratna datang ke kelurahan dengan bayi digendongan untuk mengurus akta kelahiran, tetapi antrean diperkirakan 3 jam. Sikap paling tepat adalah ....", opts:[{t:"Menyuruhnya pulang dan kembali besok pagi-pagi sekali", s:2},{t:"Membiarkannya antre normal karena semua warga sama", s:1},{t:"Mengarahkannya ke jalur prioritas ibu membawa bayi sesuai ketentuan pelayanan ramah anak", s:5},{t:"Memintanya duduk di depan loket agar tidak terlalu lama berdiri", s:4},{t:"Menjelaskan antrean memang panjang dan memintanya bersabar", s:3}], ex:"Kelompok rentan seperti ibu membawa bayi berhak atas prioritas; itulah keadilan substantif dalam pelayanan publik."},
{id:"TKP-1832", q:"Anda petugas humas dinas. Seorang influencer menawarkan promosi program dinas gratis asalkan Anda memberinya data kontak warga penerima bantuan untuk giveaway. Sikap paling tepat adalah ....", opts:[{t:"Menerima tawaran karena promosinya gratis dan menguntungkan dinas", s:2},{t:"Memberikan data sebagian kecil saja sebagai imbalan", s:1},{t:"Menolak memberikan data pribadi warga dan menawarkan kerja sama promosi tanpa data personal", s:5},{t:"Meminta izin atasan dulu sebelum memutuskan", s:3},{t:"Menolak kerja samanya sama sekali karena mencurigakan", s:4}], ex:"Data pribadi warga bukan alat barter promosi; kerja sama tetap bisa jalan tanpa mengorbankan privasi."},
{id:"TKP-1833", q:"Di loket kecamatan, seorang warga bernama Budi bersikeras ingin dilayani lebih dulu karena mengaku kenal dengan camat. Antrean lain sudah tertib. Sikap paling tepat adalah ....", opts:[{t:"Melayaninya lebih dulu agar tidak menimbulkan masalah dengan camat", s:1},{t:"Menegurnya dengan kasar di depan antrean lain", s:2},{t:"Menjelaskan dengan sopan bahwa pelayanan berdasarkan nomor antrean untuk semua warga", s:5},{t:"Memintanya menunggu sambil sesekali mengecek ke camat apakah benar kenal", s:3},{t:"Melayaninya diam-diam di sela antrean agar tidak ribut", s:4}], ex:"Menegakkan antrean secara sopan menunjukkan profesionalitas dan menolak praktik jalur orang dalam."},
{id:"TKP-1834", q:"Anda menemukan bug di aplikasi layanan dinas yang membuat data pengajuan warga bisa dilihat oleh pengguna lain. Atasan sedang cuti. Tindakan paling tepat adalah ....", opts:[{t:"Menunggu atasan kembali karena Anda tidak berwenang mengambil keputusan", s:2},{t:"Membiarkannya karena belum ada warga yang komplain", s:1},{t:"Segera menonaktifkan fitur bermasalah, memberitahu tim teknis, dan melaporkan ke atasan via pesan resmi", s:5},{t:"Memperbaikinya sendiri diam-diam tanpa dokumentasi", s:4},{t:"Mengumumkan bug tersebut ke media sosial agar warga waspada", s:3}], ex:"Kecepatan melindungi data warga didahulukan; tindakan darurat tetap didokumentasikan dan dilaporkan secara resmi."},
{id:"TKP-1835", q:"Seorang warga bernama Dedi marah karena surat izin keramaiannya ditolak padahal acara hajatan tinggal dua hari. Ia mengancam akan melapor ke media. Sikap paling tepat adalah ....", opts:[{t:"Tetap menolak tanpa menjelaskan alasan penolakan secara rinci", s:2},{t:"Menyetujui izinnya karena takut diberitakan media", s:1},{t:"Menjelaskan alasan penolakan secara rinci, syarat yang bisa dilengkapi, dan alternatif solusi yang memungkinkan", s:5},{t:"Memintanya mengajukan ulang dari awal tanpa panduan", s:3},{t:"Meneruskan ancamannya ke atasan dan menunggu perintah", s:4}], ex:"Penolakan yang dijelaskan rinci plus jalan keluar yang realistis adalah transparansi; tunduk pada ancaman merusak integritas."},
{id:"TKP-1836", q:"Anda bertugas di bagian informasi RSUD. Keluarga pasien bingung membaca rincian tagihan yang penuh istilah medis dan kode. Sikap paling tepat adalah ....", opts:[{t:"Menyuruh mereka bertanya ke dokter yang menangani saja", s:3},{t:"Menjelaskan setiap komponen tagihan dengan bahasa sederhana dan menunjukkan bukti layanannya", s:5},{t:"Memberi salinan tagihan tanpa penjelasan karena sudah jelas", s:2},{t:"Meminta mereka membayar dulu, penjelasan bisa menyusul", s:1},{t:"Menjelaskan secara umum tanpa merinci komponennya", s:4}], ex:"Transparansi biaya layanan kesehatan adalah hak pasien; penjelasan sederhana membangun kepercayaan publik."},
{id:"TKP-1837", q:"Warga bernama Maya mengadu lewat WhatsApp resmi dinas bahwa namanya salah tulis di sertifikat tanah digitalnya (satu huruf). Ia khawatir berakibat hukum. Respon paling tepat adalah ....", opts:[{t:"Menjelaskan bahwa kesalahan satu huruf tidak berpengaruh apa-apa", s:2},{t:"Menyuruhnya datang ke kantor tanpa menjelaskan berkas yang perlu dibawa", s:3},{t:"Mengonfirmasi datanya, menjelaskan prosedur koreksi, dan memandunya menyiapkan berkas yang diperlukan", s:5},{t:"Memintanya membayar biaya koreksi agar cepat diproses", s:1},{t:"Berjanji memperbaiki tanpa memintanya menyiapkan berkas apa pun", s:4}], ex:"Kesalahan data resmi harus dikoreksi prosedural; panduan berkas yang jelas menghemat bolak-balik warga."},
{id:"TKP-1838", q:"Anda melihat antrean drive-thru layanan keliling dukcapil diserobot mobil pejabat daerah yang tidak antre. Warga lain memprotes. Sikap paling tepat adalah ....", opts:[{t:"Membiarkannya lewat karena Anda takut pada pejabat tersebut", s:1},{t:"Menegur pejabat itu dengan nada tinggi di depan warga", s:2},{t:"Menjelaskan dengan sopan bahwa semua wajib antre, dan mempersilakan mengambil nomor seperti warga lain", s:5},{t:"Meminta warga yang protes untuk tenang tanpa menegakkan antrean", s:3},{t:"Melayani pejabat itu cepat-cepat agar protes warga berhenti", s:4}], ex:"Menegakkan aturan antrean tanpa pandang bulu, dengan bahasa sopan, adalah wujud kesetaraan pelayanan publik."},
{id:"TKP-1839", q:"Seorang warga lanjut usia menerima SMS yang mengatasnamakan dinas sosial, memintanya mentransfer biaya administrasi agar bansos cair. Ia datang bertanya ke Anda. Sikap paling tepat adalah ....", opts:[{t:"Menyuruhnya mentransfer saja karena mungkin memang prosedur baru", s:1},{t:"Menjelaskan bahwa itu penipuan, bansos tidak pernah dipungut biaya, dan membantunya melapor", s:5},{t:"Menjelaskan itu penipuan tanpa membantunya melapor", s:4},{t:"Memintanya mengabaikan SMS dan pulang", s:3},{t:"Menyuruhnya bertanya ke tetangganya yang lebih paham teknologi", s:2}], ex:"Edukasi anti-penipuan plus pendampingan melapor melindungi warga rentan dari korban berikutnya."},
{id:"TKP-1840", q:"Anda petugas loket di kantor imigrasi. Seorang WNA tidak bisa berbahasa Indonesia dan kebingungan dengan prosedur. Antrean di belakangnya mulai tidak sabar. Sikap paling tepat adalah ....", opts:[{t:"Menyuruhnya kembali dengan penerjemah karena petugas tidak wajib bisa bahasa asing", s:2},{t:"Mengabaikan kebingungannya dan memproses seadanya agar antrean cepat", s:1},{t:"Melayaninya dengan bahasa Inggris sederhana atau alat bantu terjemahan, tetap ramah meski antrean menunggu", s:5},{t:"Memintanya menunggu di samping sampai antrean sepi", s:3},{t:"Memprosesnya cepat tanpa penjelasan agar antrean tidak protes", s:4}], ex:"Pelayanan yang ramah lintas bahasa menunjukkan profesionalitas; ketidaksabaran antrean dikelola dengan komunikasi."},
{id:"TKP-1841", q:"Aplikasi pendaftaran online puskesmas meminta warga mengunggah foto KTP, tetapi tidak ada penjelasan untuk apa data itu dipakai. Sebagai pengelola, perbaikan paling tepat adalah ....", opts:[{t:"Membiarkannya karena semua aplikasi memang meminta data begitu", s:2},{t:"Menghapus permintaan unggah KTP agar tidak merepotkan warga", s:3},{t:"Menambahkan pemberitahuan tujuan penggunaan data dan jaminan keamanannya di aplikasi", s:5},{t:"Menambahkan penjelasan singkat tanpa jaminan keamanan", s:4},{t:"Menyembunyikan syarat unggah KTP di halaman bantuan saja", s:1}], ex:"Transparansi tujuan dan jaminan keamanan data adalah prinsip dasar perlindungan data pribadi dalam layanan digital."},
{id:"TKP-1842", q:"Warga bernama Andi melaporkan bahwa tetangganya membangun pagar menutup akses jalan umum. Ia meminta dinas segera membongkar hari ini juga. Sikap paling tepat adalah ....", opts:[{t:"Langsung memerintahkan pembongkaran hari itu juga demi kepuasan pelapor", s:1},{t:"Menjelaskan bahwa perlu verifikasi lapangan dan prosedur, lalu menjadwalkan pengecekan", s:5},{t:"Menyuruh Andi menyelesaikan secara kekeluargaan tanpa melibatkan dinas", s:2},{t:"Mencatat laporan tanpa jadwal tindak lanjut yang jelas", s:3},{t:"Berjanji menindaklanjuti secepatnya tanpa penjelasan prosedur", s:4}], ex:"Menegakkan aturan tetap butuh verifikasi dan prosedur; janji instan tanpa dasar justru maladministrasi."},
{id:"TKP-1843", q:"Anda bertugas di loket pelayanan satu pintu. Seorang warga bernama Siti membawa berkas izin yang kurang satu dokumen, dan ia sudah antre dua jam. Sikap paling tepat adalah ....", opts:[{t:"Menolak berkasnya dan menyuruhnya antre ulang lain hari", s:1},{t:"Menerima berkasnya apa adanya agar ia tidak kecewa", s:2},{t:"Menjelaskan dokumen yang kurang, memberi checklist tertulis, dan menawarkan pengiriman susulan via WhatsApp resmi", s:5},{t:"Memintanya melengkapi besok tanpa penjelasan tertulis", s:3},{t:"Menerima berkas dan berjanji menghubunginya bila ada kurang", s:4}], ex:"Checklist tertulis plus opsi susulan digital menghemat waktu warga; itulah pelayanan yang efisien dan empatik."},
{id:"TKP-1844", q:"Di media sosial beredar tangkapan layar yang diklaim sebagai surat edaran dinas Anda tentang libur tambahan, padahal dinas tidak pernah menerbitkannya. Sebagai humas, langkah paling tepat adalah ....", opts:[{t:"Membiarkannya karena toh hanya soal libur, tidak merugikan", s:2},{t:"Menyalahkan penyebar tanpa memberikan klarifikasi resmi", s:3},{t:"Menerbitkan klarifikasi resmi bahwa surat itu palsu disertai ciri surat asli dan imbauan verifikasi", s:5},{t:"Menghapus komentar yang menyebarkan tangkapan layar itu", s:1},{t:"Mengunggah surat edaran asli tanpa menyebut soal yang palsu", s:4}], ex:"Klarifikasi resmi yang edukatif (ciri asli + ajakan verifikasi) memutus rantai hoaks dokumen palsu."},
{id:"TKP-1845", q:"Seorang warga difabel kursi roda bernama Hendra kesulitan masuk ke gedung kelurahan karena tidak ada jalur landai. Ia harus diangkat oleh warga lain. Sebagai petugas, tindak lanjut paling tepat adalah ....", opts:[{t:"Meminta maaf dan mengusulkan pembangunan jalur akses disabilitas ke pimpinan secara tertulis", s:5},{t:"Membantunya masuk dengan digotong setiap kali ia datang", s:3},{t:"Menjelaskan bahwa gedung tua memang belum ada fasilitasnya", s:2},{t:"Menyuruhnya mengurus keperluan via perwakilan saja", s:1},{t:"Meminta maaf tanpa mengusulkan perbaikan apa pun", s:4}], ex:"Maaf harus disertai usulan perbaikan konkret; aksesibilitas adalah hak, bukan belas kasihan sesaat."},
{id:"TKP-1846", q:"Anda menerima telepon dari seseorang yang mengaku polisi dan meminta data alamat warga untuk penyelidikan, tetapi tidak menunjukkan surat resmi. Sikap paling tepat adalah ....", opts:[{t:"Memberikan data karena polisi pasti untuk kepentingan hukum", s:1},{t:"Menolak mentah-mentah tanpa penjelasan", s:2},{t:"Meminta surat permintaan resmi dan verifikasi ke kesatuan yang bersangkutan sebelum memberikan data", s:5},{t:"Memberikan data sebagian agar penyelidikan tidak terhambat", s:3},{t:"Memintanya datang langsung ke kantor tanpa surat", s:4}], ex:"Data warga hanya dibuka lewat permintaan resmi yang terverifikasi; klaim lisan, dari siapa pun, tidak cukup."},
{id:"TKP-1847", q:"Warga bernama Rina kecewa karena pengaduan jalan rusak yang ia sampaikan tiga bulan lalu via aplikasi tidak ada kabar. Ia datang langsung dengan nada kesal. Sikap paling tepat adalah ....", opts:[{t:"Menjelaskan bahwa pengaduan via aplikasi memang sering tidak dibaca", s:1},{t:"Memintanya membuat pengaduan baru agar tercatat ulang", s:2},{t:"Mengecek status laporannya, menjelaskan kendala anggaran, dan memberi perkiraan jadwal perbaikan", s:5},{t:"Meminta maaf tanpa mengecek status laporannya", s:4},{t:"Menjelaskan prosedur pengaduan yang benar agar lain kali tidak salah", s:3}], ex:"Mengecek status nyata dan transparan soal kendala menunjukkan pengaduan warga benar-benar ditindaklanjuti."},
{id:"TKP-1848", q:"Anda petugas di dinas perizinan. Berkas izin sebuah perusahaan sudah lengkap, tetapi atasan Anda menyuruh menunda penerbitannya karena pesaing perusahaan itu adalah kerabatnya. Sikap paling tepat adalah ....", opts:[{t:"Mematuhi atasan karena perintah pimpinan wajib dilaksanakan", s:2},{t:"Menunda penerbitan sambil mencari alasan administratif", s:1},{t:"Menolak perintah yang bertentangan dengan aturan, memproses sesuai prosedur, dan mendokumentasikan perintah tersebut", s:5},{t:"Memproses izinnya diam-diam tanpa memberitahu atasan", s:4},{t:"Meminta atasan memberikan perintah tertulis lalu menundanya", s:3}], ex:"Perintah atasan yang melanggar aturan wajib ditolak; loyalitas ASN adalah pada peraturan, bukan pada orang."},
{id:"TKP-1849", q:"Seorang ibu bernama Dewi panik di loket dukcapil karena nama anaknya salah satu huruf di KK digital, dan pendaftaran sekolah dibuka besok. Sikap paling tepat adalah ....", opts:[{t:"Menyuruhnya mendaftar sekolah dengan nama yang salah dulu, koreksi menyusul", s:2},{t:"Menolak membantu karena koreksi data butuh waktu berminggu-minggu", s:1},{t:"Memverifikasi dokumen pendukung, memproses koreksi segera, dan memberi surat keterangan sementara untuk pendaftaran sekolah", s:5},{t:"Memproses koreksi sesuai antrean normal tanpa percepatan", s:3},{t:"Membantu koreksi tetapi tanpa surat keterangan sementara", s:4}], ex:"Koreksi cepat plus solusi sementara menyelamatkan hak anak atas pendidikan; itulah keberpihakan pada warga."},
{id:"TKP-1850", q:"Anda ditugaskan memandu warga menggunakan mesin antrean mandiri di kantor pajak. Seorang bapak bernama Slamet berkali-kali salah menekan tombol dan antrean di belakangnya menumpuk. Sikap paling tepat adalah ....", opts:[{t:"Mengambil alih mesin dan menekan tombol untuknya tanpa penjelasan", s:3},{t:"Menyuruhnya minggir dan mencoba lagi setelah antrean sepi", s:2},{t:"Membiarkannya mencoba sendiri agar belajar mandiri", s:1},{t:"Mendampinginya dengan sabar, menjelaskan tiap tombol, hingga ia berhasil mengambil nomor antrean", s:5},{t:"Memanggilkan nomor manual untuknya agar antrean cepat jalan", s:4}], ex:"Kesabaran mendampingi hingga warga paham adalah inti pelayanan; jalan pintas tanpa edukasi tidak memberdayakan."},
{id:"TKP-1851", q:"Anda petugas pelayanan di kelurahan. Seorang warga bernama Fajar ingin mengurus surat keterangan usaha, tetapi ia tidak membawa surat pengantar RT karena RT-nya sedang keluar kota. Sikap paling tepat adalah ....", opts:[{t:"Menolak dan menyuruhnya kembali setelah RT pulang tanpa alternatif", s:1},{t:"Menghubungi RT via telepon untuk konfirmasi, lalu memproses dengan catatan verifikasi", s:5},{t:"Memintanya menunggu RT pulang tanpa batas waktu jelas", s:2},{t:"Meneruskan ke lurah agar lurah yang memutuskan", s:3},{t:"Memproses suratnya dengan syarat ia berjanji menyusul surat pengantar", s:4}], ex:"Konfirmasi langsung ke RT menyelesaikan hambatan prosedural tanpa mengorbankan validitas dokumen."},
{id:"TKP-1852", q:"Beredar broadcast WhatsApp yang mencatut nama dinas Anda, menjanjikan bantuan modal usaha dengan syarat mengisi formulir berisi data rekening. Banyak warga bertanya ke call center. Respon paling tepat adalah ....", opts:[{t:"Menjawab satu per satu bahwa itu penipuan tanpa pengumuman resmi", s:4},{t:"Mengabaikan karena broadcast bukan dikeluarkan dinas", s:2},{t:"Menyalahkan warga yang mudah percaya pada broadcast", s:1},{t:"Menerbitkan peringatan resmi di semua kanal, melaporkan nomor penyebar, dan membuka posko klarifikasi", s:5},{t:"Meminta warga menghapus broadcast tersebut", s:3}], ex:"Peringatan resmi multi-kanal plus pelaporan adalah perlindungan proaktif terhadap warga dari penipuan yang mencatut institusi."},
{id:"TKP-1853", q:"Anda melayani di loket BPJS kesehatan. Seorang peserta bernama Agus kebingungan karena tagihannya membengkak akibat denda, padahal ia merasa sudah membayar. Sikap paling tepat adalah ....", opts:[{t:"Menyuruhnya membayar denda dulu, protes bisa belakangan", s:1},{t:"Menjelaskan bahwa sistem tidak mungkin salah", s:2},{t:"Mengecek riwayat pembayaran, menjelaskan asal denda dengan rinci, dan membantu pengajuan keringanan bila memenuhi syarat", s:5},{t:"Mengarahkannya ke bank tempat ia membayar tanpa pengecekan", s:3},{t:"Mengecek riwayatnya dan menjelaskan sekilas tanpa solusi", s:4}], ex:"Verifikasi data plus penjelasan rinci dan jalan keluar keringanan adalah pelayanan yang adil dan transparan."},
{id:"TKP-1854", q:"Seorang warga tuna rungu bernama Dedi datang ke dinas sosial didampingi anaknya yang masih kecil sebagai penerjemah. Sikap paling tepat adalah ....", opts:[{t:"Melayaninya melalui anaknya karena tidak ada pilihan lain", s:3},{t:"Memintanya kembali dengan penerjemah dewasa yang kompeten", s:2},{t:"Berkomunikasi dengan bahasa isyarat dasar atau tulisan, memastikan Dedi sendiri yang memahami dan memutuskan", s:5},{t:"Menolak melayani karena terkendala komunikasi", s:1},{t:"Memproses keperluannya cepat-cepat melalui anaknya agar antrean lancar", s:4}], ex:"Memastikan penyandang disabilitas memahami langsung keputusannya adalah penghormatan pada otonomi dan martabatnya."},
{id:"TKP-1855", q:"Anda menemukan data pribadi ribuan warga (nama, NIK, alamat) tersimpan di laptop pribadi rekan kerja yang sering dibawa ke warung kopi. Tindakan paling tepat adalah ....", opts:[{t:"Membiarkannya karena itu tanggung jawab rekan tersebut", s:2},{t:"Mengingatkan rekan secara pribadi tentang risikonya dan melaporkannya ke atasan bila tidak diindahkan", s:5},{t:"Menghapus data itu dari laptopnya diam-diam", s:3},{t:"Menyebarkan ke grup kantor agar rekan itu malu dan jera", s:1},{t:"Mengingatkan sekali tanpa tindak lanjut bila diabaikan", s:4}], ex:"Data warga di perangkat pribadi tanpa pengamanan adalah pelanggaran serius; diingatkan lalu dilaporkan bila berlanjut."},
{id:"TKP-1856", q:"Warga bernama Maya mengajukan izin mendirikan bangunan, tetapi lokasinya berada di zona hijau. Ia memohon diberi pengecualian karena sudah terlanjur membeli material. Sikap paling tepat adalah ....", opts:[{t:"Memberi pengecualian karena material sudah dibeli dan ia warga setempat", s:1},{t:"Menolak sambil menjelaskan aturan zonasi dan mengarahkan ke lokasi alternatif yang sesuai", s:5},{t:"Menolak tanpa penjelasan detail soal zonasi", s:2},{t:"Meneruskan permohonannya ke atasan tanpa rekomendasi", s:3},{t:"Menunda keputusan agar ia tidak kecewa hari ini", s:4}], ex:"Aturan tata ruang tidak bisa dinegosiasi dengan alasan terlanjur; penolakan yang solutif tetap manusiawi."},
{id:"TKP-1857", q:"Anda admin media sosial puskesmas. Seorang warga berkomentar menanyakan hasil lab milik pasien lain yang kebetulan tetangganya. Respon paling tepat adalah ....", opts:[{t:"Menjawabnya via DM karena kasihan pada yang bertanya", s:1},{t:"Mengabaikan komentarnya", s:2},{t:"Menjelaskan bahwa hasil lab bersifat rahasia dan hanya diberikan ke pasien atau keluarga yang berwenang", s:5},{t:"Memintanya datang ke puskesmas untuk menanyakan langsung", s:3},{t:"Menjawab singkat bahwa tidak bisa dibagikan tanpa penjelasan", s:4}], ex:"Kerahasiaan data kesehatan pasien adalah kewajiban etik; penolakan dijelaskan dengan dasar yang jelas."},
{id:"TKP-1858", q:"Antrean pengambilan STNK di Samsat mengular hingga ke parkiran. Sistem menyebut waktu tunggu 4 jam. Sebagai koordinator, langkah paling tepat adalah ....", opts:[{t:"Membiarkan antrean apa adanya karena keterbatasan petugas", s:2},{t:"Menutup pendaftaran agar antrean tidak bertambah panjang", s:1},{t:"Membuka loket tambahan, menerapkan pemanggilan bergelombang, dan mengumumkan estimasi waktu secara berkala", s:5},{t:"Meminta warga pulang dan kembali besok", s:3},{t:"Mempercepat pelayanan dengan memangkas verifikasi berkas", s:4}], ex:"Menambah kapasitas, mengatur gelombang, dan komunikasi estimasi waktu adalah manajemen antrean yang profesional."},
{id:"TKP-1859", q:"Seorang lansia bernama Ratna menangis di loket karena ditolak mencairkan bantuan dengan alasan data tidak padan, padahal ia sudah antre sejak subuh. Sikap paling tepat adalah ....", opts:[{t:"Tetap menolak sesuai data sistem tanpa penjelasan", s:1},{t:"Menyuruhnya pulang dan memperbaiki data di dukcapil dulu", s:2},{t:"Menenangkannya, mengecek detail ketidakpadanan, dan memandu langkah perbaikan data sampai tuntas", s:5},{t:"Mencairkan bantuan secara manual agar ia tidak menangis", s:4},{t:"Memintanya kembali besok dengan berkas lengkap", s:3}], ex:"Empati plus pendampingan perbaikan data hingga tuntas jauh lebih membantu daripada penolakan dingin atau jalan pintas."},
{id:"TKP-1860", q:"Anda menerima pesan WhatsApp dari warga yang mengirim foto KTP-nya dan meminta Anda mengecek status pengajuan bantuan. Ia mengirim ke nomor pribadi Anda yang didapat dari temannya. Sikap paling tepat adalah ....", opts:[{t:"Mengeceknya langsung karena kasihan dan datanya sudah ada", s:2},{t:"Mengabaikan pesan dan memblokir nomornya", s:1},{t:"Menjelaskan bahwa layanan hanya via kanal resmi, menghapus foto KTP dari ponsel, dan mengarahkannya ke kanal resmi", s:5},{t:"Mengecek statusnya lalu memintanya tidak mengulangi lagi", s:4},{t:"Meneruskan foto KTP itu ke grup kerja agar dibantu", s:3}], ex:"Menjaga batas kanal resmi dan menghapus data pribadi yang masuk via jalur tak resmi melindungi privasi warga."},
{id:"TKP-1861", q:"Di ruang tunggu kantor pajak, dua warga bertengkar memperebutkan kursi. Suasana memanas dan mengganggu pelayanan. Sebagai petugas, tindakan paling tepat adalah ....", opts:[{t:"Membiarkan mereka bertengkar sampai selesai sendiri", s:1},{t:"Mengusir keduanya dari ruang tunggu", s:2},{t:"Melerai dengan tenang, menempatkan mereka terpisah, dan memastikan pelayanan tetap berjalan", s:5},{t:"Memanggil satpam untuk mengamankan tanpa melerai dulu", s:3},{t:"Menyuruh salah satu mengalah demi ketertiban", s:4}], ex:"Melerai dengan tenang dan memisahkan pihak bertikai menjaga ketertiban tanpa mempermalukan warga."},
{id:"TKP-1862", q:"Anda ditugaskan menyosialisasikan aplikasi layanan digital desa ke warga. Mayoritas warga adalah petani lanjut usia yang gaptek. Strategi paling tepat adalah ....", opts:[{t:"Membagikan brosur panduan aplikasi dan berharap mereka mempelajarinya", s:2},{t:"Menyatakan sosialisasi gagal karena warga tidak mampu", s:1},{t:"Menggelar demo langsung dengan bahasa sederhana, melibatkan kader desa sebagai pendamping, dan membuka layanan bantuan", s:5},{t:"Meminta anak-anak mereka yang mengajarkan di rumah", s:3},{t:"Menyederhanakan aplikasi tanpa sosialisasi langsung", s:4}], ex:"Edukasi langsung yang kontekstual plus pendamping kader memastikan transformasi digital inklusif bagi semua warga."},
{id:"TKP-1863", q:"Seorang warga bernama Joko melapor bahwa paket bantuan yang diterimanya tidak sesuai daftar (beras diganti merek murah). Ia curiga ada penyelewengan. Tindak lanjut paling tepat adalah ....", opts:[{t:"Menjelaskan bahwa merek bisa berbeda-beda tergantung stok", s:3},{t:"Menyuruhnya menerima saja karena bantuan itu gratis", s:1},{t:"Mencatat laporan, memverifikasi ke distributor dan gudang, serta menindaklanjuti bila terbukti ada penyimpangan", s:5},{t:"Mengganti paketnya dengan yang baru tanpa investigasi", s:4},{t:"Menyalahkan warga karena terlalu banyak menuntut", s:2}], ex:"Setiap dugaan penyelewengan bantuan diverifikasi faktual; pembiaran merusak kepercayaan publik pada program sosial."},
{id:"TKP-1864", q:"Anda petugas call center dinas. Seorang penelepon marah-marah menuduh dinas mempersulit izinnya, padahal ia belum melengkapi syarat. Sikap paling tepat adalah ....", opts:[{t:"Menutup telepon karena ia tidak sopan", s:1},{t:"Membalas dengan nada tinggi agar ia sadar", s:2},{t:"Tetap tenang, mendengarkan, lalu menjelaskan syarat yang kurang dengan bahasa yang mudah dipahami", s:5},{t:"Menyuruhnya membaca website dinas sendiri", s:3},{t:"Mencatat keluhannya tanpa menjelaskan solusinya", s:4}], ex:"Profesionalitas call center diuji saat penelepon emosional; ketenangan plus penjelasan solutif adalah standar layanan."},
{id:"TKP-1865", q:"Warga bernama Siti menemukan namanya terdaftar sebagai penerima bantuan di aplikasi, tetapi ia tidak pernah merasa mendaftar. Ia khawatir datanya disalahgunakan. Sikap paling tepat adalah ....", opts:[{t:"Menjelaskan mungkin ada kesalahan input dan memintanya tidak khawatir", s:3},{t:"Menyuruhnya membiarkan saja karena toh ia dapat bantuan", s:1},{t:"Memverifikasi sumber pendaftarannya, menelusuri dugaan pencatutan, dan mengamankan datanya", s:5},{t:"Menghapus namanya dari daftar tanpa investigasi", s:4},{t:"Menyuruhnya melapor ke polisi sendiri", s:2}], ex:"Dugaan pencatutan data harus ditelusuri sumbernya; penghapusan tanpa investigasi menghilangkan jejak pelaku."},
{id:"TKP-1866", q:"Anda melihat rekan kerja menerima bingkisan parsel dari warga yang baru selesai mengurus izin. Rekan berdalih itu tanda terima kasih biasa. Sikap paling tepat adalah ....", opts:[{t:"Ikut menerima bagian parsel karena sudah terlanjur diberi", s:1},{t:"Membiarkannya karena nilainya kecil dan wajar sebagai ucapan terima kasih", s:2},{t:"Mengingatkan bahwa gratifikasi dalam bentuk apa pun dilarang dan menyarankan mengembalikan atau melaporkan", s:5},{t:"Melaporkannya ke atasan tanpa mengingatkannya dulu", s:3},{t:"Menasihatinya agar lain kali menerima diam-diam", s:4}], ex:"Gratifikasi sekecil apa pun dilarang bagi ASN; mengingatkan lalu melaporkan adalah penegakan integritas berjenjang."},
{id:"TKP-1867", q:"Seorang ibu bernama Dewi mengadu di loket bahwa anaknya dirundung di sekolah dan pihak sekolah tidak merespons laporannya. Ia meminta dinas pendidikan turun tangan. Sikap paling tepat adalah ....", opts:[{t:"Menyuruhnya menyelesaikan dengan pihak sekolah karena bukan wewenang dinas", s:2},{t:"Langsung menyalahkan pihak sekolah di depan ibu tersebut", s:1},{t:"Mencatat kronologi, meneruskan ke bidang terkait, dan memberi tahu ibu itu alur serta estimasi tindak lanjutnya", s:5},{t:"Mencatat laporannya tanpa memberi tahu alur tindak lanjut", s:3},{t:"Berjanji akan menegur kepala sekolahnya besok", s:4}], ex:"Laporan perundungan ditangani serius lewat jalur resmi dengan kepastian alur bagi pelapor, bukan janji teguran lisan."},
{id:"TKP-1868", q:"Anda mengelola grup WhatsApp resmi layanan kelurahan. Seorang anggota menyebar iklan pinjaman online ilegal di grup. Tindakan paling tepat adalah ....", opts:[{t:"Membiarkannya karena bukan wewenang mengatur promosi warga", s:2},{t:"Menghapus iklan, mengingatkan aturan grup, dan bila berulang mengeluarkannya dari grup", s:5},{t:"Langsung mengeluarkannya tanpa peringatan", s:3},{t:"Ikut mempromosikan karena mungkin bermanfaat bagi warga", s:1},{t:"Menghapus iklan tanpa penjelasan aturan", s:4}], ex:"Grup resmi harus steril dari konten ilegal; penegakan bertahap (peringatan lalu sanksi) adalah moderasi yang adil."},
{id:"TKP-1869", q:"Warga bernama Budi protes karena biaya pengurusan surat di kelurahan berbeda dengan yang tertera di papan informasi. Petugas loket meminta biaya tambahan. Sikap paling tepat sebagai atasannya adalah ....", opts:[{t:"Menjelaskan bahwa biaya tambahan itu untuk mempercepat proses", s:1},{t:"Meminta warga membayar sesuai papan informasi dan menginvestigasi dugaan pungli petugas", s:5},{t:"Meminta maaf dan mengembalikan ke biaya resmi tanpa investigasi", s:4},{t:"Menyuruh warga melapor tertulis bila keberatan", s:3},{t:"Membela petugas karena mungkin ada biaya operasional tak tertulis", s:2}], ex:"Tarif resmi wajib ditegakkan; selisih biaya tanpa dasar adalah pungli yang harus diinvestigasi, bukan dinormalisasi."},
{id:"TKP-1870", q:"Anda petugas arsip. Seorang warga meminta salinan surat keputusan lama milik almarhum ayahnya untuk urusan waris. Dokumennya ada tetapi berstatus arsip terbatas. Sikap paling tepat adalah ....", opts:[{t:"Menolak karena statusnya arsip terbatas tanpa pengecualian", s:2},{t:"Memberikannya langsung karena ia ahli waris yang sah", s:3},{t:"Memverifikasi identitas dan hubungan ahli waris, lalu memberikan salinan sesuai prosedur keterbukaan informasi", s:5},{t:"Memberikannya dengan imbalan uang rokok karena prosesnya rumit", s:1},{t:"Menyuruhnya kembali dengan surat kuasa pengacara", s:4}], ex:"Ahli waris yang terverifikasi berhak atas dokumen untuk urusan waris; prosedur memastikan hak sekaligus keamanan arsip."},
{id:"TKP-1871", q:"Aplikasi antrean online RSUD menampilkan nomor Anda sudah lewat padahal Anda merasa belum dipanggil karena sempat ke toilet. Petugas memanggil nomor berikutnya. Sikap paling tepat sebagai warga yang dilayani dengan baik adalah ....", opts:[{t:"Konteks ini dari sudut petugas: menjelaskan dengan sabar, mengecek sistem, dan mengatur ulang antreannya secara adil", s:5},{t:"Menyuruhnya mengambil nomor baru dari awal tanpa pengecualian", s:2},{t:"Membentaknya karena meninggalkan ruang tunggu", s:1},{t:"Menyelipkannya ke antrean saat ini tanpa pencatatan", s:4},{t:"Memintanya menunggu sampai semua antrean selesai", s:3}], ex:"Mengecek fakta sistem dan mengatur ulang secara adil menyeimbangkan ketertiban antrean dengan empati pada warga."},
{id:"TKP-1872", q:"Anda menemukan akun media sosial palsu yang mengatasnamakan kepala dinas dan meminta warga mentransfer uang untuk percepatan layanan. Tindakan paling tepat adalah ....", opts:[{t:"Membiarkannya karena bukan akun resmi dinas", s:2},{t:"Menghubungi pemilik akun untuk meminta klarifikasi", s:3},{t:"Melaporkan akun ke platform, menerbitkan peringatan resmi, dan berkoordinasi dengan aparat", s:5},{t:"Mengomentari akun palsu itu agar pengikutnya tahu", s:4},{t:"Menunggu ada korban melapor baru bertindak", s:1}], ex:"Penindakan proaktif (lapor platform, peringatan resmi, koordinasi aparat) mencegah jatuhnya korban penipuan."},
{id:"TKP-1873", q:"Seorang warga bernama Putri ingin mengadukan pelayanan buruk, tetapi takut identitasnya diketahui petugas yang diadukan. Ia meminta jaminan kerahasiaan. Sikap paling tepat adalah ....", opts:[{t:"Menolak menerima aduan tanpa identitas jelas", s:2},{t:"Menjamin kerahasiaan identitas pelapor sesuai mekanisme whistleblowing dan memproses aduannya", s:5},{t:"Menerima aduan tetapi memberitahu identitasnya ke atasan petugas", s:1},{t:"Menyarankan mengadu langsung ke petugasnya agar cepat selesai", s:3},{t:"Menerima aduan tanpa menjelaskan mekanisme perlindungannya", s:4}], ex:"Jaminan kerahasiaan pelapor adalah prasyarat keberanian melapor; mekanisme perlindungan harus dijelaskan eksplisit."},
{id:"TKP-1874", q:"Anda bertugas di posko bencana banjir. Bantuan logistik terbatas sementara warga yang membutuhkan membludak. Prinsip distribusi paling tepat adalah ....", opts:[{t:"Membagikan ke siapa yang datang lebih dulu agar cepat habis", s:2},{t:"Memberikan ke warga yang paling vokal menuntut agar tidak ribut", s:1},{t:"Mendata kebutuhan, memprioritaskan kelompok rentan (lansia, ibu hamil, anak), dan transparan soal keterbatasan stok", s:5},{t:"Membagi rata semua paket tanpa pendataan agar adil", s:4},{t:"Menunda distribusi sampai bantuan tambahan datang", s:3}], ex:"Prioritas berbasis kerentanan plus transparansi stok adalah distribusi darurat yang adil dan akuntabel."},
{id:"TKP-1875", q:"Warga bernama Andi mengirim email pengaduan dengan bahasa kasar dan ancaman akan memviralkan dinas. Isi aduannya valid soal pungli di loket. Sikap paling tepat adalah ....", opts:[{t:"Mengabaikan aduan karena bahasanya kasar dan mengancam", s:1},{t:"Membalas dengan bahasa kasar agar ia jera", s:2},{t:"Fokus pada substansi aduan: investigasi dugaan pungli, sambil menjawab dengan bahasa profesional", s:5},{t:"Memproses aduan tetapi menegurnya soal etika berkomunikasi", s:4},{t:"Meneruskan email ke atasan tanpa tindak lanjut", s:3}], ex:"Substansi aduan yang valid wajib ditindaklanjuti apa pun bahasanya; profesionalitas dijaga dalam respons."},
{id:"TKP-1876", q:"Anda petugas pendaftaran tanah. Seorang warga membawa sertifikat yang diduga palsu untuk balik nama. Ia tidak sadar dan mengaku membelinya dari makelar. Sikap paling tepat adalah ....", opts:[{t:"Memproses balik nama agar warga tidak kecewa", s:1},{t:"Menuduhnya sebagai pemalsu dan mengusirnya", s:2},{t:"Menahan proses, menjelaskan dugaan kepalsuan dengan hati-hati, dan mengarahkannya ke jalur hukum yang benar", s:5},{t:"Menolak memproses tanpa menjelaskan alasannya", s:3},{t:"Menyarankan mencari makelarnya untuk menyelesaikan diam-diam", s:4}], ex:"Dugaan dokumen palsu ditangani prosedural tanpa menghakimi; warga yang mungkin korban diarahkan ke jalur hukum."},
{id:"TKP-1877", q:"Seorang ibu hamil bernama Rina antre di loket pembayaran PDAM. Ia terlihat pucat dan berkeringat. Petugas loket tetap melayani sesuai nomor. Sebagai pengawas, tindakan paling tepat adalah ....", opts:[{t:"Membiarkan sesuai antrean karena semua warga sama", s:2},{t:"Menyuruhnya pulang dan membayar via aplikasi saja", s:1},{t:"Segera memprioritaskannya, memastikan kondisinya aman, dan mengevaluasi SOP prioritas kelompok rentan", s:5},{t:"Memberinya kursi untuk duduk sambil tetap menunggu nomornya", s:4},{t:"Meminta warga lain mengalah tanpa intervensi petugas", s:3}], ex:"Kondisi darurat kesehatan warga didahulukan; evaluasi SOP mencegah kejadian berulang."},
{id:"TKP-1878", q:"Anda menerima kiriman data warga via email pribadi dari rekan kerja untuk keperluan verifikasi bansos. Email itu tidak terenkripsi. Sikap paling tepat adalah ....", opts:[{t:"Menggunakannya seperti biasa karena dari rekan sendiri", s:2},{t:"Meneruskan ke email pribadi Anda agar mudah dikerjakan di rumah", s:1},{t:"Menghapus dari email pribadi, meminta pengiriman ulang via kanal resmi yang aman, dan mengingatkan rekan", s:5},{t:"Menggunakannya lalu menghapus emailnya", s:4},{t:"Mengabaikan email dan tidak memverifikasi data", s:3}], ex:"Data warga tidak boleh transit di email pribadi; meminta jalur aman resmi adalah disiplin perlindungan data."},
{id:"TKP-1879", q:"Warga bernama Hendra kecewa karena jalan di depan rumahnya diperbaiki asal-asalan oleh kontraktor proyek dinas. Ia meminta Anda meninjau langsung. Sikap paling tepat adalah ....", opts:[{t:"Menjelaskan bahwa kualitas proyek adalah tanggung jawab kontraktor, bukan dinas", s:2},{t:"Berjanji akan menegur kontraktor tanpa verifikasi lapangan", s:4},{t:"Menjadwalkan peninjauan lapangan, mendokumentasikan temuan, dan menindaklanjuti ke kontraktor via mekanisme kontrak", s:5},{t:"Menyuruhnya melapor ke kontraktor langsung", s:3},{t:"Menyalahkan warga karena tidak mengawasi saat pengerjaan", s:1}], ex:"Dinas bertanggung jawab atas kualitas proyeknya; verifikasi lapangan dan tindak lanjut kontraktual adalah akuntabilitas."},
{id:"TKP-1880", q:"Anda admin aplikasi layanan. Seorang warga melaporkan tombol bayar tidak berfungsi dan ia sudah terdebet dua kali. Ia panik dan menuntut pengembalian hari ini juga. Respon paling tepat adalah ....", opts:[{t:"Menyuruhnya menunggu proses refund maksimal 14 hari tanpa penjelasan", s:3},{t:"Menjelaskan itu kesalahan bank dan menyuruhnya menghubungi bank", s:2},{t:"Menenangkannya, memverifikasi transaksi ganda, mengajukan refund prioritas, dan memberi nomor tiket pelacakan", s:5},{t:"Berjanji refund hari ini juga meski di luar kewenangan", s:4},{t:"Mengabaikan karena nominalnya kecil", s:1}], ex:"Verifikasi cepat, pengajuan refund prioritas, dan tiket pelacakan memberi kepastian; janji di luar kewenangan merusak kepercayaan."},
{id:"TKP-1881", q:"Seorang warga lanjut usia bernama Slamet ingin mengurus perpanjangan KTP tetapi sidik jarinya tidak terbaca mesin karena kulitnya menipis. Sikap paling tepat adalah ....", opts:[{t:"Menyuruhnya kembali lain waktu siapa tahu mesinnya membaik", s:2},{t:"Menolak melayani karena verifikasi biometrik wajib", s:1},{t:"Menggunakan metode verifikasi alternatif sesuai SOP (dokumen pendukung + saksi) dengan sabar", s:5},{t:"Memintanya menggosok jarinya agar terbaca mesin", s:3},{t:"Melewati verifikasi tanpa prosedur alternatif", s:4}], ex:"SOP verifikasi alternatif untuk lansia memastikan hak warga tidak gugur karena keterbatasan biometrik."},
{id:"TKP-1882", q:"Anda melihat unggahan di media sosial yang menuduh dinas Anda menggelapkan dana bantuan, disertai foto karung beras yang sobek. Unggahan itu viral. Langkah paling tepat adalah ....", opts:[{t:"Menuntut penyebar unggahan atas pencemaran nama baik", s:1},{t:"Mengabaikan karena tuduhan tidak berdasar", s:2},{t:"Mengumpulkan fakta distribusi, menerbitkan klarifikasi terbuka, dan membuka audit bila diperlukan", s:5},{t:"Membantah singkat tanpa data pendukung", s:4},{t:"Meminta warganet berhenti menyebarkan tanpa klarifikasi", s:3}], ex:"Tuduhan dana publik dijawab dengan fakta dan keterbukaan audit; ancaman hukum tanpa klarifikasi justru memperkeruh."},
{id:"TKP-1883", q:"Warga bernama Dedi datang ke kecamatan membawa surat rujukan palsu yang dibuatkannya sendiri agar dilayani jalur prioritas. Ia mengaku terpaksa karena butuh cepat. Sikap paling tepat adalah ....", opts:[{t:"Melayaninya karena alasannya mendesak dan manusiawi", s:2},{t:"Membentaknya dan melaporkannya ke polisi saat itu juga", s:1},{t:"Menjelaskan bahwa dokumen palsu tidak bisa diterima, menolak prioritas, dan tetap melayaninya via jalur normal", s:5},{t:"Menerima suratnya tanpa memeriksa keasliannya", s:4},{t:"Menyuruhnya pulang dan kembali dengan surat asli", s:3}], ex:"Ketegasan menolak dokumen palsu diimbangi pelayanan normal yang manusiawi; empati tidak membenarkan pemalsuan."},
{id:"TKP-1884", q:"Anda petugas di dinas kependudukan. Seorang ibu bernama Nur ingin mendaftarkan anak angkatnya ke dalam KK, tetapi tidak paham prosedur adopsi resmi. Sikap paling tepat adalah ....", opts:[{t:"Menyuruhnya mengurus adopsi resmi dulu tanpa menjelaskan caranya", s:3},{t:"Menolak karena adopsi tanpa putusan pengadilan tidak sah", s:2},{t:"Menjelaskan alur adopsi resmi langkah demi langkah, syarat dokumennya, dan instansi yang dituju", s:5},{t:"Mendaftarkan anak itu ke KK tanpa prosedur adopsi agar cepat", s:1},{t:"Memberi brosur umum tanpa penjelasan personal", s:4}], ex:"Penjelasan alur yang rinci memberdayakan warga menempuh jalur hukum yang benar, bukan jalan pintas administratif."},
{id:"TKP-1885", q:"Seorang warga mengirim pesan ke WhatsApp resmi dinas pada pukul 23.00 menanyakan syarat izin yang mendesak untuk esok pagi. Sebagai petugas piket humas, respon paling tepat adalah ....", opts:[{t:"Mengabaikan karena di luar jam kerja", s:2},{t:"Menjawab dengan jawaban asal agar ia tidak menunggu", s:1},{t:"Menjawab dengan info syarat yang akurat atau template resmi, serta mengarahkan ke layanan pagi hari bila perlu verifikasi", s:5},{t:"Membalas singkat menyuruhnya datang pagi-pagi", s:3},{t:"Menjawab seadanya tanpa memastikan keakuratan info", s:4}], ex:"Kanal resmi yang responsif di luar jam kerja dengan info akurat menunjukkan komitmen pelayanan prima."},
{id:"TKP-1886", q:"Anda koordinator loket. Seorang petugas kedapatan meminta warga mengisi survei kepuasan dengan nilai sempurna agar target tercapai. Sikap paling tepat adalah ....", opts:[{t:"Membiarkannya karena target survei memang harus tercapai", s:1},{t:"Menegur petugas itu di depan warga agar jera", s:2},{t:"Menegur dan membina petugas, serta memastikan survei diisi warga secara jujur dan sukarela", s:5},{t:"Melaporkannya ke atasan tanpa pembinaan langsung", s:3},{t:"Memintanya tidak mengulangi tanpa menjelaskan mengapa itu salah", s:4}], ex:"Memalsukan survei kepuasan merusak fungsi evaluasi; integritas data layanan tidak boleh dikorbankan demi target."},
{id:"TKP-1887", q:"Warga bernama Maya melaporkan via aplikasi bahwa lampu jalan di gangnya mati sudah dua minggu dan rawan begal. Status laporannya masih belum diproses. Tindak lanjut paling tepat adalah ....", opts:[{t:"Menjelaskan bahwa perbaikan lampu butuh anggaran tahun depan", s:2},{t:"Mengabaikan karena banyak laporan lain yang antre", s:1},{t:"Mengecek status, mengoordinasikan perbaikan prioritas karena aspek keamanan, dan mengabari pelapor progresnya", s:5},{t:"Meneruskan ke dinas terkait tanpa memantau tindak lanjutnya", s:3},{t:"Berjanji segera diperbaiki tanpa koordinasi nyata", s:4}], ex:"Laporan yang menyangkut keamanan warga diprioritaskan dan progresnya dikomunikasikan; lempar tanggung jawab tanpa pantau adalah abai."},
{id:"TKP-1888", q:"Seorang warga difabel netra ingin mengakses informasi layanan di website dinas, tetapi website tidak ramah pembaca layar. Ia mengadu ke Anda sebagai pengelola. Tindak lanjut paling tepat adalah ....", opts:[{t:"Menyarankannya datang langsung ke kantor saja", s:2},{t:"Menjelaskan bahwa website memang belum mendukung dan memintanya bersabar", s:3},{t:"Menyampaikan kebutuhan aksesibilitas ke tim pengembang, menyediakan alternatif info, dan memantau perbaikannya", s:5},{t:"Mengabaikan karena hanya satu orang yang komplain", s:1},{t:"Membacakan isi website via telepon tanpa tindak lanjut perbaikan", s:4}], ex:"Aksesibilitas digital adalah hak; aduan ditindaklanjuti ke pengembang dengan solusi sementara yang manusiawi."},
{id:"TKP-1889", q:"Anda petugas di kantor kelurahan. Seorang warga bernama Agus meminta dibuatkan surat keterangan domisili untuk alamat yang bukan tempat tinggalnya, dengan alasan untuk syarat kerja. Sikap paling tepat adalah ....", opts:[{t:"Membuatkannya karena kasihan ia butuh pekerjaan", s:1},{t:"Menolak dan melaporkannya sebagai penipu", s:2},{t:"Menolak dengan penjelasan bahwa surat harus sesuai fakta, dan mengarahkan membuat surat sesuai domisili sebenarnya", s:5},{t:"Meneruskannya ke lurah agar lurah yang memutuskan", s:3},{t:"Menunda dengan alasan blangko habis", s:4}], ex:"Surat keterangan harus sesuai fakta; penolakan yang memberi jalan keluar sah menjaga integritas dokumen negara."},
{id:"TKP-1890", q:"Di loket puskesmas, seorang pasien bernama Fajar bersikeras minta antibiotik tanpa resep dokter karena merasa sudah tahu penyakitnya. Sikap paling tepat adalah ....", opts:[{t:"Memberikannya agar ia tidak marah dan antrean cepat", s:1},{t:"Menolak dengan kasar karena ia bukan tenaga medis", s:2},{t:"Menjelaskan dengan sabar bahaya resistensi antibiotik dan mengarahkannya ke pemeriksaan dokter", s:5},{t:"Menyuruhnya membeli di apotek luar saja", s:3},{t:"Menolak tanpa menjelaskan alasannya", s:4}], ex:"Edukasi bahaya antibiotik tanpa resep melindungi kesehatan publik; penolakan harus dibarengi penjelasan."},
{id:"TKP-1891", q:"Anda menerima laporan bahwa data antrean online dinas bisa dimanipulasi calo untuk menjual nomor antrean prioritas. Tindakan paling tepat adalah ....", opts:[{t:"Membiarkannya karena calo membantu warga yang malas antre", s:1},{t:"Menutup layanan antrean online dan kembali ke manual", s:2},{t:"Mengamankan sistem (verifikasi identitas, batasan akun), menindak calo, dan mengedukasi warga agar tidak membeli nomor", s:5},{t:"Mengumumkan agar warga tidak membeli nomor tanpa perbaikan sistem", s:4},{t:"Melaporkan ke atasan dan menunggu instruksi", s:3}], ex:"Menutup celah sistem plus penindakan dan edukasi memberantas percaloan sampai ke akarnya."},
{id:"TKP-1892", q:"Seorang ibu bernama Ratna bingung karena tagihan listriknya melonjak tiga kali lipat. Ia datang ke kantor pelayanan terpadu meminta penjelasan. Sikap paling tepat adalah ....", opts:[{t:"Menyuruhnya langsung ke kantor PLN karena bukan wewenang Anda", s:2},{t:"Menjelaskan bahwa tarif memang naik tanpa memeriksa datanya", s:3},{t:"Membantu mengecek riwayat pemakaian, menjelaskan kemungkinan penyebab, dan memfasilitasi pengaduan ke PLN", s:5},{t:"Menyuruhnya membayar dulu baru komplain", s:1},{t:"Memberi nomor call center PLN tanpa membantu mengecek", s:4}], ex:"Membantu menelusuri akar masalah dan memfasilitasi pengaduan adalah pelayanan terpadu yang memudahkan warga."},
{id:"TKP-1893", q:"Anda ditugaskan mendata warga penerima bantuan. Seorang ketua RT meminta agar kerabatnya dimasukkan meski tidak memenuhi syarat. Sikap paling tepat adalah ....", opts:[{t:"Memasukkannya karena menjaga hubungan baik dengan RT penting", s:2},{t:"Menolak dan mengancam akan melaporkannya", s:1},{t:"Menolak dengan tegas, menjelaskan kriteria penerima, dan mendokumentasikan permintaan tersebut", s:5},{t:"Menolak tanpa menjelaskan kriterianya", s:4},{t:"Meneruskan permintaan itu ke atasan tanpa pendirian", s:3}], ex:"Kriteria bansos tidak bisa dinegosiasi relasi; penolakan tegas plus dokumentasi menjaga akuntabilitas pendataan."},
{id:"TKP-1894", q:"Warga bernama Dedi mengunggah video ke media sosial yang memperlihatkan petugas dinas Anda tertidur saat jam pelayanan. Video itu viral dan memalukan instansi. Langkah paling tepat adalah ....", opts:[{t:"Menuntut warga yang mengunggah video atas pencemaran nama baik", s:1},{t:"Mengabaikan video karena hanya oknum", s:2},{t:"Memverifikasi kejadian, menindaklanjuti pembinaan petugas, dan menyampaikan klarifikasi serta komitmen perbaikan", s:5},{t:"Membela petugas dengan alasan kelelahan tanpa investigasi", s:3},{t:"Meminta warga menghapus video tanpa tindak lanjut internal", s:4}], ex:"Fakta diverifikasi, oknum dibina, publik diberi klarifikasi; menutupi atau menyerang balik merusak kepercayaan."},
{id:"TKP-1895", q:"Seorang warga bernama Putri ingin mengajukan keberatan atas hasil seleksi administrasi CPNS daerah. Ia tidak paham cara mengajukan sanggah online. Sikap paling tepat adalah ....", opts:[{t:"Menyuruhnya membaca pengumuman sendiri karena sudah jelas", s:2},{t:"Menolak membantu karena masa sanggah hampir habis", s:1},{t:"Memandunya langkah demi langkah mengajukan sanggah via portal, memastikan keberatannya tersampaikan sebelum batas waktu", s:5},{t:"Mengarahkannya ke website tanpa pendampingan", s:3},{t:"Membantunya mengisi tetapi tanpa menjelaskan isi sanggahannya", s:4}], ex:"Hak sanggah adalah hak peserta; pendampingan hingga tuntas memastikan hak itu benar-benar terpenuhi."},
{id:"TKP-1896", q:"Anda petugas kebersihan kantor dinas menemukan amplop berisi uang di ruang tunggu loket tanpa identitas pemilik. Tindakan paling tepat adalah ....", opts:[{t:"Mengambilnya karena tidak ada yang tahu pemiliknya", s:1},{t:"Membaginya dengan rekan kerja yang menemukan bersama", s:2},{t:"Menyerahkan ke bagian keamanan/pimpinan untuk diumumkan sebagai barang temuan sesuai prosedur", s:5},{t:"Menyimpannya sendiri sambil menunggu ada yang mencari", s:4},{t:"Mengumumkannya di media sosial pribadi", s:3}], ex:"Barang temuan diserahkan lewat prosedur resmi; mengambilnya adalah penggelapan yang mencoreng integritas ASN."},
{id:"TKP-1897", q:"Seorang warga tuna daksa bernama Hendra ingin menggunakan layanan mandiri di aplikasi, tetapi aplikasinya tidak mendukung navigasi keyboard. Ia mengadu ke helpdesk. Respon paling tepat adalah ....", opts:[{t:"Menyarankannya meminta bantuan orang lain saja", s:2},{t:"Menjelaskan keterbatasan aplikasi dan memintanya bersabar", s:3},{t:"Meneruskan kebutuhan aksesibilitasnya ke tim teknis, memberi solusi alternatif sementara, dan mengabari progres perbaikan", s:5},{t:"Mengabaikan karena penggunanya sedikit", s:1},{t:"Memberi panduan penggunaan tanpa meneruskan ke tim teknis", s:4}], ex:"Aduan aksesibilitas ditindaklanjuti ke pengembang dengan solusi sementara; inklusi digital bukan opsional."},
{id:"TKP-1898", q:"Warga bernama Joko melapor bahwa ia diminta biaya fotokopi berkas oleh petugas loket padahal papan informasi menyebut layanan gratis. Sebagai atasan, tindak lanjut paling tepat adalah ....", opts:[{t:"Menganggapnya masalah kecil karena nominal fotokopi sedikit", s:2},{t:"Membela petugas karena mungkin untuk operasional", s:1},{t:"Menginvestigasi, mengembalikan pungutan bila terbukti, membina petugas, dan menegaskan tarif resmi ke publik", s:5},{t:"Meminta maaf tanpa investigasi dan pengembalian", s:4},{t:"Meminta warga membuat laporan tertulis dulu", s:3}], ex:"Pungutan sekecil apa pun di luar tarif resmi adalah pungli; investigasi, pengembalian, dan pembinaan menuntaskannya."},
{id:"TKP-1899", q:"Anda mengelola data kependudukan. Seorang calon legislatif meminta daftar pemilih beserta nomor ponselnya untuk kampanye. Sikap paling tepat adalah ....", opts:[{t:"Memberikannya karena untuk kepentingan demokrasi", s:1},{t:"Memberikan daftar nama tanpa nomor ponsel", s:2},{t:"Menolak karena data pribadi warga tidak boleh dipakai untuk kepentingan politik praktis", s:5},{t:"Memintanya mengajukan surat resmi ke KPU dulu", s:3},{t:"Menolak tanpa menjelaskan dasar hukumnya", s:4}], ex:"Data kependudukan bukan komoditas kampanye; netralitas ASN melarang memfasilitasi kepentingan politik praktis."},
{id:"TKP-1900", q:"Seorang ibu bernama Siti panik karena surat nikahnya sobek dimakan rayap dan ia butuh untuk mengurus akta anak. Sikap paling tepat adalah ....", opts:[{t:"Menyuruhnya menikah ulang secara resmi agar dapat surat baru", s:1},{t:"Menolak membantu karena dokumen rusak bukan tanggung jawab dinas", s:2},{t:"Mengecek arsip pencatatan, menerbitkan kutipan akta nikah pengganti sesuai prosedur, dan memandu syaratnya", s:5},{t:"Menerbitkan surat baru tanpa verifikasi arsip", s:4},{t:"Memintanya mengurus ke pengadilan tanpa penjelasan", s:3}], ex:"Arsip negara memungkinkan penerbitan kutipan pengganti; verifikasi arsip menjaga keabsahan dokumen."},
{id:"TKP-1901", q:"Anda petugas di dinas perizinan. Seorang warga bernama Budi mengajukan izin usaha kuliner, tetapi lokasinya dekat sekolah dan dikhawatirkan mengganggu. Sikap paling tepat adalah ....", opts:[{t:"Menolak mentah-mentah tanpa kajian karena dekat sekolah", s:2},{t:"Menyetujui karena ia sudah menyiapkan modal besar", s:1},{t:"Memproses sesuai kajian teknis dan aturan zonasi, menjelaskan hasilnya transparan apa pun keputusannya", s:5},{t:"Meneruskan ke atasan tanpa kajian teknis", s:3},{t:"Menunda keputusan sampai ada protes warga sekitar", s:4}], ex:"Keputusan perizinan berbasis kajian teknis dan aturan, bukan tekanan modal atau asumsi; transparansi hasilnya menjaga kepercayaan."},
{id:"TKP-1902", q:"Beredar kabar di media sosial bahwa dinas Anda akan menghapus data kependudukan warga yang tidak memperbarui KK tahun ini. Banyak warga panik datang ke kantor. Respon paling tepat adalah ....", opts:[{t:"Membiarkan warga panik agar mereka tertib memperbarui data", s:1},{t:"Menjelaskan satu per satu ke warga yang datang tanpa pengumuman resmi", s:4},{t:"Mengabaikan kabar karena jelas hoaks", s:2},{t:"Segera menerbitkan bantahan resmi di semua kanal dan membuka layanan informasi untuk warga yang cemas", s:5},{t:"Meminta warga tidak menyebarkan kabar tanpa klarifikasi resmi", s:3}], ex:"Hoaks yang menimbulkan kepanikan dijawab cepat lewat klarifikasi resmi multi-kanal plus layanan informasi."},
{id:"TKP-1903", q:"Seorang warga bernama Rina datang ke puskesmas membawa resep dokter yang tulisannya tidak terbaca. Ia meminta obat segera karena anaknya menunggu. Sikap paling tepat adalah ....", opts:[{t:"Menebak-nebak isi resep agar pelayanan cepat", s:1},{t:"Menolak melayani sampai ia kembali ke dokter", s:2},{t:"Menghubungi dokter penulis resep untuk konfirmasi sebelum memberikan obat yang tepat", s:5},{t:"Memberikan obat yang paling umum untuk gejalanya", s:4},{t:"Memintanya menunggu sampai dokternya selesai praktik", s:3}], ex:"Keselamatan pasien tidak boleh dikorbankan demi kecepatan; konfirmasi ke dokter adalah prosedur yang wajib."},
{id:"TKP-1904", q:"Anda bertugas di loket pengaduan. Seorang warga difabel intelektual datang didampingi keluarganya untuk melaporkan KTP yang hilang. Sikap paling tepat adalah ....", opts:[{t:"Berbicara hanya dengan keluarganya dan mengabaikan warga tersebut", s:2},{t:"Menolak melayani karena khawatir keterangannya tidak valid", s:1},{t:"Berkomunikasi langsung dengannya dengan bahasa sederhana dan sabar, melibatkan keluarga sebagai pendamping", s:5},{t:"Memproses laporannya cepat-cepat melalui keluarganya", s:4},{t:"Memintanya kembali dengan surat keterangan dokter", s:3}], ex:"Berkomunikasi langsung dengan penyandang disabilitas menghormati martabatnya; keluarga berperan sebagai pendamping, bukan pengganti."},
{id:"TKP-1905", q:"Seorang rekan kerja mengajak Anda memanipulasi data kehadiran agar terlihat lembur dan dapat uang lembur. Sikap paling tepat adalah ....", opts:[{t:"Menolak tegas dan mengingatkan bahwa itu fraud anggaran negara", s:5},{t:"Ikut serta karena semua rekan melakukannya", s:1},{t:"Menolak ikut tetapi membiarkan rekan melanjutkannya", s:3},{t:"Melaporkannya diam-diam tanpa menegur lebih dulu", s:4},{t:"Menolak dengan alasan takut ketahuan, bukan karena prinsip", s:2}], ex:"Menolak fraud anggaran adalah integritas; menegur rekan sebelum melapor adalah pembinaan berjenjang yang adil."},
{id:"TKP-1906", q:"Warga bernama Dewi mengeluh antrean loket kecamatan selalu didahulukan oleh warga yang membawa anak kecil padahal ia juga buru-buru kerja. Sikap paling tepat menjelaskan adalah ....", opts:[{t:"Menyalahkan ibu-ibu yang membawa anak karena seenaknya", s:1},{t:"Menjelaskan bahwa prioritas kelompok rentan adalah kebijakan resmi demi keadilan, bukan pilih kasih", s:5},{t:"Memintanya maklum saja tanpa menjelaskan dasar kebijakan", s:3},{t:"Berjanji akan menghapus jalur prioritas agar adil", s:2},{t:"Menjelaskan sekilas tanpa menyebut dasar aturannya", s:4}], ex:"Kebijakan prioritas dijelaskan dengan dasar keadilannya agar warga memahami, bukan sekadar diminta maklum."},
{id:"TKP-1907", q:"Anda menemukan formulir pengajuan warga berisi data NIK dan KK berserakan di meja fotokopi kantor. Tindakan paling tepat adalah ....", opts:[{t:"Membiarkannya karena bukan dokumen Anda", s:2},{t:"Membuangnya ke tempat sampah agar meja bersih", s:1},{t:"Mengamankan dokumen, mengembalikannya ke bagian terkait, dan mengingatkan soal kerapian pengelolaan data", s:5},{t:"Mengambilnya dan menyimpannya di laci Anda", s:4},{t:"Memotretnya untuk bukti kelalaian rekan", s:3}], ex:"Dokumen berisi data pribadi yang tercecer wajib diamankan dan dikembalikan lewat jalur resmi, bukan dibuang."},
{id:"TKP-1908", q:"Seorang warga bernama Agus ingin membayar pajak kendaraan, tetapi STNK-nya atas nama orang lain yang sudah meninggal dan ia tidak punya surat kuasa ahli waris. Sikap paling tepat adalah ....", opts:[{t:"Menolak dan menyuruhnya balik nama dulu tanpa menjelaskan caranya", s:2},{t:"Memproses pembayaran apa adanya demi target penerimaan", s:1},{t:"Menjelaskan prosedur balik nama waris langkah demi langkah dan membantu menyiapkan syaratnya", s:5},{t:"Meneruskannya ke atasan tanpa penjelasan", s:3},{t:"Memberi daftar syarat tanpa penjelasan detail", s:4}], ex:"Menjelaskan alur balik nama waris secara rinci mengubah penolakan menjadi pemberdayaan warga."},
{id:"TKP-1909", q:"Akun media sosial dinas Anda diretas dan dipakai menyebar tautan judi online. Banyak warga sudah mengklik. Langkah paling tepat adalah ....", opts:[{t:"Menghapus postingan judi dan berharap warga lupa", s:2},{t:"Membiarkannya sampai tim IT datang besok", s:1},{t:"Segera mengamankan akun, mengumumkan peretasan ke publik, dan mengimbau warga tidak mengklik serta mengganti kata sandi bila sempat login", s:5},{t:"Membuat akun baru tanpa pengumuman", s:4},{t:"Melaporkan ke platform tanpa memberitahu warga", s:3}], ex:"Transparansi soal peretasan plus imbauan pengamanan melindungi warga yang terlanjur mengklik tautan berbahaya."},
{id:"TKP-1910", q:"Warga bernama Maya datang ke kelurahan meminta surat keterangan belum menikah untuk syarat CPNS, tetapi data di KK menunjukkan ia pernah menikah. Sikap paling tepat adalah ....", opts:[{t:"Membuatkan surat sesuai permintaannya karena untuk CPNS", s:1},{t:"Menuduhnya berbohong dan mengusirnya", s:2},{t:"Menjelaskan ketidaksesuaian data, menolak menerbitkan yang tidak sesuai fakta, dan mengarahkan perbaikan data yang benar", s:5},{t:"Meneruskannya ke lurah tanpa penjelasan", s:3},{t:"Menunda dengan alasan sistem sedang gangguan", s:4}], ex:"Dokumen negara harus sesuai fakta; penolakan disertai arahan perbaikan data adalah integritas yang solutif."},
{id:"TKP-1911", q:"Anda petugas di RSUD. Keluarga pasien miskin meminta keringanan biaya operasi. Prosedurnya rumit dan butuh waktu. Sikap paling tepat adalah ....", opts:[{t:"Menyuruhnya membayar penuh dulu, keringanan diurus belakangan", s:1},{t:"Menjelaskan prosedur keringanan rumit dan menyarankan mencari pinjaman", s:2},{t:"Membantu menyiapkan berkas keringanan, mengoordinasikan dengan bagian sosial, dan memastikan operasi tidak tertunda untuk kasus darurat", s:5},{t:"Memberi formulir keringanan tanpa pendampingan", s:4},{t:"Menyarankan pindah ke rumah sakit lain yang lebih murah", s:3}], ex:"Nyawa pasien didahulukan; pendampingan berkas keringanan memastikan kemiskinan tidak menghalangi layanan kesehatan."},
{id:"TKP-1912", q:"Seorang warga mengirimkan kritik pedas via email resmi dinas soal pelayanan yang lambat, lengkap dengan data dan saran perbaikan. Sikap paling tepat adalah ....", opts:[{t:"Mengabaikan karena kritiknya menyakitkan", s:2},{t:"Membalas dengan pembelaan panjang soal keterbatasan anggaran", s:3},{t:"Menyerang balik karena merasa sudah bekerja maksimal", s:1},{t:"Menyampaikan terima kasih, menindaklanjuti saran yang feasible, dan mengabari hasilnya ke pengirim", s:5},{t:"Meneruskan ke atasan tanpa membalas pengirim", s:4}], ex:"Kritik berbasis data adalah masukan berharga; ditindaklanjuti dan diberi umpan balik menunjukkan kedewasaan institusi."},
{id:"TKP-1913", q:"Anda melihat sopir ambulans dinas menggunakan ambulans untuk mengantar keluarganya berbelanja di pasar. Tindakan paling tepat adalah ....", opts:[{t:"Membiarkannya karena ambulans sedang tidak dipakai", s:2},{t:"Ikut menumpang karena kebetulan searah", s:1},{t:"Menegur sopir dan melaporkan penyalahgunaan aset negara ke atasan", s:5},{t:"Memotretnya untuk disebar ke media sosial", s:3},{t:"Menegur saja tanpa melapor karena kasihan", s:4}], ex:"Aset negara untuk pelayanan darurat tidak boleh dipakai pribadi; ditegur dan dilaporkan lewat jalur resmi."},
{id:"TKP-1914", q:"Warga bernama Fajar ingin mengurus surat izin keramaian untuk acara pernikahan, tetapi lokasinya berdekatan dengan rumah ibadah yang sedang ada kegiatan. Sikap paling tepat adalah ....", opts:[{t:"Menolak izinnya mentah-mentah demi menghindari konflik", s:2},{t:"Menyetujui karena hajatan hanya sekali seumur hidup", s:1},{t:"Memfasilitasi koordinasi waktu dengan pengurus rumah ibadah agar kedua kegiatan berjalan tanpa mengganggu", s:5},{t:"Menyetujui dengan syarat volumenya kecil tanpa koordinasi", s:4},{t:"Meneruskan ke polisi tanpa memfasilitasi dialog", s:3}], ex:"Memfasilitasi dialog antarwarga mencegah konflik; izin yang bijak mempertimbangkan semua pihak."},
{id:"TKP-1915", q:"Seorang lansia bernama Nur menerima telepon dari orang yang mengaku petugas dinas sosial, memintanya menyebutkan nomor rekening untuk pencairan bansos. Ia datang panik ke Anda. Sikap paling tepat adalah ....", opts:[{t:"Menyuruhnya memberikan saja karena mungkin memang prosedur", s:1},{t:"Menjelaskan itu modus penipuan, memintanya tidak memberikan data apa pun, dan membantu melapor", s:5},{t:"Menjelaskan itu penipuan tanpa membantu melapor", s:4},{t:"Menyuruhnya mengganti nomor teleponnya", s:2},{t:"Memintanya menunggu sampai ada korban lain baru melapor", s:3}], ex:"Edukasi cepat plus pendampingan lapor melindungi lansia dari penipuan yang mengatasnamakan institusi."},
{id:"TKP-1916", q:"Anda koordinator pelayanan. Hasil survei menunjukkan kepuasan warga turun karena petugas dinilai jutek. Langkah perbaikan paling tepat adalah ....", opts:[{t:"Menyalahkan warga yang terlalu sensitif", s:1},{t:"Memasang poster senyum di loket tanpa pembinaan", s:2},{t:"Mengadakan pembinaan komunikasi pelayanan, simulasi, dan monitoring berkala dengan indikator jelas", s:5},{t:"Mengingatkan petugas sekali via grup WhatsApp", s:4},{t:"Menyembunyikan hasil survei agar tidak mempermalukan", s:3}], ex:"Perbaikan perilaku layanan butuh pembinaan sistematis dan monitoring, bukan sekadar imbauan atau kosmetik."},
{id:"TKP-1917", q:"Warga bernama Dedi mengajukan permohonan informasi publik soal anggaran proyek jalan di desanya. Ia berhak menurut undang-undang. Sikap paling tepat adalah ....", opts:[{t:"Menolak dengan alasan dokumen bersifat internal", s:1},{t:"Mempersulit dengan prosedur berbelit agar ia menyerah", s:2},{t:"Memproses permohonannya sesuai UU Keterbukaan Informasi, memberi salinan yang tidak dikecualikan tepat waktu", s:5},{t:"Memberi informasi secara lisan tanpa dokumen", s:4},{t:"Meneruskan ke atasan dan membiarkannya menunggu tanpa batas", s:3}], ex:"Keterbukaan informasi publik adalah hak warga yang dijamin undang-undang; diproses tepat waktu dan prosedural."},
{id:"TKP-1918", q:"Anda petugas loket di dukcapil. Seorang warga bernama Joko marah karena e-KTP-nya rusak chipnya dan ia disuruh merekam ulang dari awal. Sikap paling tepat adalah ....", opts:[{t:"Menyuruhnya menerima prosedur apa adanya tanpa penjelasan", s:2},{t:"Membentaknya karena marah-marah di loket", s:1},{t:"Menjelaskan alasan perekaman ulang dengan sabar, memandu prosesnya, dan memastikan datanya tidak hilang", s:5},{t:"Memintanya datang lain hari saat mesin tidak sibuk", s:3},{t:"Memproses perekaman ulang tanpa penjelasan", s:4}], ex:"Penjelasan sabar soal alasan teknis plus pendampingan mengubah kemarahan menjadi pengertian."},
{id:"TKP-1919", q:"Di aplikasi lapor, seorang warga mengunggah foto tumpukan sampah di sungai disertai lokasi akurat. Ia kecewa karena laporan serupa tahun lalu tak digubris. Tindak lanjut paling tepat adalah ....", opts:[{t:"Menjelaskan bahwa kebersihan sungai bukan wewenang dinas Anda", s:2},{t:"Menghapus laporannya karena menyudutkan dinas", s:1},{t:"Memverifikasi lokasi, mengoordinasikan pembersihan dengan dinas terkait, dan mengabari pelapor jadwalnya", s:5},{t:"Meneruskan ke dinas terkait tanpa memantau", s:3},{t:"Berjanji membersihkan tanpa koordinasi nyata", s:4}], ex:"Laporan berbasis bukti direspons dengan verifikasi, koordinasi lintas dinas, dan kabar progres ke warga."},
{id:"TKP-1920", q:"Seorang warga bernama Siti ingin mendaftarkan usaha kulinernya ke aplikasi pesan-antar, tetapi butuh NIB. Ia tidak paham OSS. Sikap paling tepat adalah ....", opts:[{t:"Menyuruhnya belajar sendiri lewat tutorial YouTube", s:2},{t:"Menolak membantu karena OSS adalah sistem pusat", s:3},{t:"Memandunya mendaftar NIB via OSS langkah demi langkah hingga terbit", s:5},{t:"Menawarkan jasa pembuatan NIB dengan biaya", s:1},{t:"Memberi brosur OSS tanpa pendampingan", s:4}], ex:"Pendampingan hingga NIB terbit memberdayakan UMKM; pungutan jasa oleh petugas adalah pelanggaran."},
{id:"TKP-1921", q:"Anda menerima pesan berantai yang mengklaim vaksin di puskesmas Anda kedaluwarsa, disertai foto yang buram. Banyak warga membatalkkan imunisasi anaknya. Langkah paling tepat adalah ....", opts:[{t:"Membiarkannya karena foto buktinya tidak jelas", s:2},{t:"Menyalahkan orang tua yang mudah panik", s:1},{t:"Memverifikasi stok vaksin, menerbitkan klarifikasi dengan bukti tanggal kedaluwarsa, dan mengajak warga kembali imunisasi", s:5},{t:"Mengunggah foto stok vaksin tanpa penjelasan", s:4},{t:"Meminta warga tidak percaya tanpa bukti bantahan", s:3}], ex:"Hoaks kesehatan dilawan dengan verifikasi faktual dan bukti terbuka; nyawa anak dipertaruhkan bila dibiarkan."},
{id:"TKP-1922", q:"Warga bernama Andi protes karena namanya dieja salah di surat keterangan yang baru diterbitkan, padahal ia sudah menunggu lama. Sikap paling tepat adalah ....", opts:[{t:"Menyalahkan Andi karena tidak memeriksa draf sebelumnya", s:1},{t:"Menyuruhnya mengajukan permohonan baru dari awal", s:2},{t:"Meminta maaf, memperbaiki segera tanpa antre ulang, dan mengevaluasi proses verifikasi nama", s:5},{t:"Memperbaiki tetapi memintanya antre ulang seperti biasa", s:3},{t:"Memperbaiki tanpa meminta maaf atas kesalahan", s:4}], ex:"Kesalahan instansi diperbaiki segera dengan prioritas plus evaluasi proses; warga tidak boleh menanggung akibatnya."},
{id:"TKP-1923", q:"Anda petugas di kantor pajak. Seorang wajib pajak mengaku tidak menerima surat tagihan sehingga kena denda. Ia meminta denda dihapus. Sikap paling tepat adalah ....", opts:[{t:"Menghapus dendanya agar ia tidak protes", s:1},{t:"Menolak mentah-mentah karena denda sudah sistem", s:2},{t:"Mengecek riwayat pengiriman tagihan, menjelaskan hasilnya jujur, dan memproses penghapusan bila terbukti tidak terkirim", s:5},{t:"Menjelaskan prosedur keberatan tanpa mengecek riwayat", s:3},{t:"Mengurangi dendanya sebagian sebagai kompromi", s:4}], ex:"Keputusan berbasis verifikasi data pengiriman adalah keadilan administratif; bukan asal hapus atau asal tolak."},
{id:"TKP-1924", q:"Seorang ibu membawa anak balita yang rewel ke loket kelurahan. Ia terlihat kewalahan mengurus berkas sambil menggendong. Sikap paling tepat adalah ....", opts:[{t:"Membiarkannya berjuang sendiri karena itu urusannya", s:2},{t:"Menyuruhnya pulang dan kembali tanpa anak", s:1},{t:"Menawarkan bantuan memegangi berkas atau memprioritaskan pelayanannya agar cepat selesai", s:5},{t:"Mempercepat pelayanan tanpa menawarkan bantuan", s:4},{t:"Memintanya tenang agar tidak mengganggu loket lain", s:3}], ex:"Inisiatif membantu ibu yang kewalahan adalah empati konkret yang membuat pelayanan terasa manusiawi."},
{id:"TKP-1925", q:"Anda menemukan celah di website dinas yang memungkinkan siapa pun mengunduh daftar nama dan alamat warga. Belum ada bukti disalahgunakan. Tindakan paling tepat adalah ....", opts:[{t:"Menantu sampai ada penyalahgunaan baru bertindak", s:1},{t:"Menutup website sementara tanpa pemberitahuan", s:2},{t:"Segera menutup celah, mengaudit akses yang terjadi, dan melaporkan ke pimpinan serta warga bila data terdampak", s:5},{t:"Memperbaiki diam-diam tanpa audit dan pelaporan", s:4},{t:"Melaporkan ke atasan dan menunggu perintah tanpa tindakan teknis", s:3}], ex:"Celah keamanan data ditutup segera, diaudit, dan dilaporkan transparan; menunggu korban adalah kelalaian."},
{id:"TKP-1926", q:"Warga bernama Hendra ingin mengurus surat ahli waris, tetapi salah satu ahli waris berada di luar negeri dan sulit dihubungi. Sikap paling tepat adalah ....", opts:[{t:"Menolak memproses sampai semua ahli waris hadir fisik", s:2},{t:"Memproses tanpa melibatkan ahli waris yang jauh agar cepat", s:1},{t:"Menjelaskan opsi surat kuasa bermeterai/konsuler dan memandu prosesnya sesuai ketentuan", s:5},{t:"Meneruskan ke notaris tanpa penjelasan", s:3},{t:"Memberi daftar syarat tanpa menjelaskan opsi kuasa jarak jauh", s:4}], ex:"Solusi surat kuasa resmi menjembatani kendala jarak tanpa melanggar hak ahli waris lain."},
{id:"TKP-1927", q:"Anda admin WhatsApp resmi dinas. Seorang warga mengirim pesan bernada melecehkan petugas perempuan di loket. Tindakan paling tepat adalah ....", opts:[{t:"Membalas dengan makian agar ia jera", s:1},{t:"Mengabaikan karena hanya pesan teks", s:2},{t:"Menegur dengan tegas namun profesional, mengingatkan batasan, dan memblokir bila berulang", s:5},{t:"Meneruskan pesan itu ke grup kantor sebagai bahan tertawaan", s:4},{t:"Memintanya meminta maaf tanpa konsekuensi", s:3}], ex:"Pelecehan terhadap petugas ditindak tegas-profesional; martabat ASN dilindungi tanpa terpancing emosi."},
{id:"TKP-1928", q:"Seorang warga bernama Ratna mengeluh tagihan airnya tidak wajar padahal ia jarang di rumah. Petugas loket menyuruhnya membayar saja. Sebagai pengawas, tindak lanjut paling tepat adalah ....", opts:[{t:"Membela petugas karena prosedurnya memang begitu", s:2},{t:"Menyuruh warga membayar dulu baru komplain", s:1},{t:"Mengarahkan pengecekan meteran, menjelaskan hasil temuan, dan mengoreksi tagihan bila terbukti salah catat", s:5},{t:"Memberi nomor pengaduan tanpa tindak lanjut", s:3},{t:"Menjanjikan pengecekan tanpa jadwal pasti", s:4}], ex:"Keluhan tagihan dijawab dengan pengecekan faktual meteran, bukan perintah membayar buta."},
{id:"TKP-1929", q:"Anda ditugaskan membuat panduan layanan digital untuk warga. Banyak istilah teknis yang membingungkan. Pendekatan paling tepat adalah ....", opts:[{t:"Menggunakan istilah teknis apa adanya karena itu bahasa resmi", s:2},{t:"Tidak membuat panduan karena warga pasti tidak membaca", s:1},{t:"Menulis dengan bahasa sederhana, ilustrasi langkah bergambar, dan mengujinya ke warga awam sebelum dipublikasikan", s:5},{t:"Menyalin panduan dari daerah lain tanpa adaptasi", s:3},{t:"Membuat panduan teks panjang tanpa ilustrasi", s:4}], ex:"Panduan diuji ke warga awam memastikan benar-benar dipahami; itulah komunikasi publik yang efektif."},
{id:"TKP-1930", q:"Warga bernama Joko menemukan dompet berisi uang dan KTP di ruang tunggu kantor Anda. Ia menyerahkannya ke Anda. Tindakan paling tepat adalah ....", opts:[{t:"Mengambil sebagian uangnya sebagai ucapan terima kasih untuk Joko", s:1},{t:"Menyuruh Joko menyimpannya saja", s:2},{t:"Mencatat sebagai barang temuan, mengumumkan via pengeras suara/papan, dan mengembalikannya ke pemilik dengan verifikasi", s:5},{t:"Menyimpannya di laci tanpa pengumuman", s:4},{t:"Mengumumkan tanpa pencatatan resmi", s:3}], ex:"Barang temuan dikelola prosedural (catat, umumkan, verifikasi pemilik) agar kembali ke tangan yang berhak."},
{id:"TKP-1931", q:"Anda petugas pendaftaran di dinas sosial. Seorang warga mengaku janda untuk mendapatkan bantuan, tetapi tetangganya melaporkan ia masih bersuami. Sikap paling tepat adalah ....", opts:[{t:"Langsung mencoret namanya dari daftar penerima", s:2},{t:"Menuduhnya penipu di depan warga lain", s:1},{t:"Memverifikasi fakta lewat dokumen dan kunjungan lapangan sebelum memutuskan status bantuannya", s:5},{t:"Tetap memberinya bantuan agar tidak ribut", s:4},{t:"Menyuruhnya membawa surat keterangan janda dari RT", s:3}], ex:"Dugaan ketidakjujuran diverifikasi faktual sebelum sanksi; praduga tak bersalah berlaku juga dalam layanan sosial."},
{id:"TKP-1932", q:"Seorang warga lanjut usia tidak bisa membaca notifikasi di aplikasi layanan karena tulisannya terlalu kecil. Ia mengadu ke helpdesk. Respon paling tepat adalah ....", opts:[{t:"Menyarankannya memakai kacamata yang lebih kuat", s:2},{t:"Mengabaikan karena standar aplikasi sudah begitu", s:1},{t:"Meneruskan masukan aksesibilitas ke tim pengembang dan memandunya mengatur ukuran teks perangkat sementara", s:5},{t:"Membacakan notifikasinya via telepon tanpa meneruskan masukan", s:4},{t:"Menjelaskan bahwa aplikasi memang dirancang untuk pengguna muda", s:3}], ex:"Masukan aksesibilitas diteruskan ke pengembang dengan solusi sementara; desain inklusif melayani semua usia."},
{id:"TKP-1933", q:"Anda melihat rekan kerja membuang berkas pengajuan warga yang menurutnya ribet ke tempat sampah. Tindakan paling tepat adalah ....", opts:[{t:"Membiarkannya karena bukan berkas yang Anda tangani", s:2},{t:"Mengambil berkas dari sampah dan memprosesnya diam-diam", s:4},{t:"Ikut membuang berkas serupa agar pekerjaan ringan", s:1},{t:"Menegur rekan, mengamankan berkas, dan melaporkan perilakunya ke atasan", s:5},{t:"Menasihatinya tanpa mengamankan dan melaporkan", s:3}], ex:"Membuang berkas warga adalah maladministrasi berat; ditegur, diamankan, dan dilaporkan lewat jalur resmi."},
{id:"TKP-1934", q:"Warga bernama Dedi ingin melaporkan pungli, tetapi loket pengaduan offline membuatnya takut terlihat. Ia bertanya apakah bisa melapor anonim via digital. Sikap paling tepat adalah ....", opts:[{t:"Menjelaskan tidak bisa karena semua laporan harus bernama jelas", s:2},{t:"Menyuruhnya berani melapor terbuka saja", s:3},{t:"Mengarahkannya ke kanal lapor anonim resmi, menjelaskan perlindungannya, dan memastikan laporannya ditindaklanjuti", s:5},{t:"Menerima laporannya via pesan pribadi Anda", s:4},{t:"Menolak membantu karena takut ikut terseret", s:1}], ex:"Kanal lapor anonim yang aman mendorong keberanian melapor pungli; perlindungannya dijelaskan eksplisit."},
{id:"TKP-1935", q:"Anda petugas humas. Wartawan meminta konfirmasi soal dugaan kebocoran data warga di dinas Anda sebelum berita terbit. Sikap paling tepat adalah ....", opts:[{t:"Menolak berkomentar dan menghindar dari wartawan", s:2},{t:"Membantah total tanpa memeriksa fakta", s:1},{t:"Mengoordinasikan verifikasi internal cepat, memberi pernyataan resmi yang jujur, dan menjelaskan langkah penanganan", s:5},{t:"Meminta wartawan menunda berita tanpa penjelasan", s:3},{t:"Memberi komentar pribadi yang belum terverifikasi", s:4}], ex:"Krisis data dijawab dengan verifikasi cepat dan pernyataan resmi yang jujur; bungkam atau bantah buta merusak kredibilitas."},
{id:"TKP-1936", q:"Seorang warga bernama Maya datang dengan surat kuasa dari ibunya yang sakit untuk mengurus BPJS. Petugas menolak karena surat kuasa dianggap tidak sah. Sikap paling tepat menengahi adalah ....", opts:[{t:"Mendukung penolakan petugas tanpa memeriksa surat kuasa", s:2},{t:"Memaksa petugas menerima surat kuasa itu", s:1},{t:"Memeriksa keabsahan surat kuasa, menjelaskan syaratnya bila kurang, dan membantu melengkapinya", s:5},{t:"Menyuruh Maya kembali dengan ibunya yang sakit", s:3},{t:"Menerima surat kuasa tanpa verifikasi agar cepat", s:4}], ex:"Surat kuasa diverifikasi keabsahannya; warga dibantu melengkapi, bukan ditolak mentah atau diterima buta."},
{id:"TKP-1937", q:"Anda menemukan postingan di media sosial yang memfitnah pribadi kepala dinas dengan foto editan. Banyak warganet mempercayainya. Langkah paling tepat sebagai humas adalah ....", opts:[{t:"Menyerang balik penyebar dengan ujaran kebencian", s:1},{t:"Mengabaikan karena menyerang pribadi, bukan institusi", s:2},{t:"Menerbitkan klarifikasi faktual, melaporkan konten manipulatif ke platform, dan menempuh jalur hukum bila perlu", s:5},{t:"Meminta warganet berhenti menyebar tanpa klarifikasi", s:3},{t:"Menghapus komentar yang membahasnya di akun dinas", s:4}], ex:"Fitnah dijawab fakta, dilaporkan ke platform, dan jalur hukum disiapkan; emosi tidak boleh mengendalikan respons institusi."},
{id:"TKP-1938", q:"Warga bernama Budi mengeluh proses izin usahanya berbulan-bulan tanpa kejelasan di dinas Anda. Ia membawa bukti tanda terima. Sikap paling tepat adalah ....", opts:[{t:"Menyalahkan bagian lain yang menangani berkasnya", s:2},{t:"Memintanya bersabar karena antrean memang panjang", s:3},{t:"Menelusuri posisi berkasnya, menjelaskan hambatannya jujur, dan mempercepat sesuai koridor aturan", s:5},{t:"Berjanji selesai minggu ini tanpa menelusuri dulu", s:4},{t:"Menyuruhnya mengurus ulang dari awal", s:1}], ex:"Menelusuri berkas nyata dan transparan soal hambatan adalah akuntabilitas; janji manis tanpa dasar merusak kepercayaan."},
{id:"TKP-1939", q:"Seorang ibu hamil tua terjatuh di tangga kantor kelurahan yang licin dan tidak ada pegangan. Sebagai petugas, tindak lanjut paling tepat adalah ....", opts:[{t:"Menyalahkan ibu itu karena tidak hati-hati", s:1},{t:"Membantunya berdiri lalu melupakan kejadian", s:2},{t:"Memastikan kondisinya aman, mengantar ke puskesmas bila perlu, dan mengusulkan perbaikan fasilitas tangga", s:5},{t:"Meminta maaf tanpa mengusulkan perbaikan", s:4},{t:"Menunggu keluarga menjemput tanpa tindakan", s:3}], ex:"Keselamatan warga didahulukan, lalu akar masalah fasilitas diperbaiki agar tidak terulang."},
{id:"TKP-1940", q:"Anda mengelola database penerima bantuan. Atasan meminta Anda mengubah data agar wilayahnya terlihat terbanyak menerima bantuan untuk pencitraan. Sikap paling tepat adalah ....", opts:[{t:"Mengubahnya karena perintah atasan dan hanya soal tampilan", s:1},{t:"Mengubah sebagian agar tidak terlalu mencolok", s:2},{t:"Menolak memanipulasi data, menjelaskan risikonya, dan mendokumentasikan permintaan tersebut", s:5},{t:"Menolak tanpa dokumentasi", s:4},{t:"Meminta perintah tertulis lalu mengubahnya", s:3}], ex:"Integritas data publik tidak bisa dimanipulasi untuk pencitraan; penolakan didokumentasikan sebagai perlindungan diri dan institusi."},
{id:"TKP-1941", q:"Warga bernama Siti kecewa karena anaknya tidak diterima di sekolah negeri favorit via zonasi padahal rumahnya dekat. Ia menuduh ada permainan. Sikap paling tepat adalah ....", opts:[{t:"Membela sistem zonasi tanpa menunjukkan data", s:2},{t:"Menuduhnya tidak paham aturan", s:1},{t:"Menunjukkan data jarak dan kuota secara transparan serta menjelaskan mekanisme sanggah yang tersedia", s:5},{t:"Menjelaskan aturan zonasi secara umum tanpa data", s:4},{t:"Menyarankannya pindah ke sekolah swasta saja", s:3}], ex:"Tuduhan permainan dijawab dengan data transparan dan jalur sanggah resmi, bukan pembelaan kosong."},
{id:"TKP-1942", q:"Anda petugas di loket imigrasi. Seorang warga bernama Agus kehilangan paspor di luar negeri dan butuh surat pengganti untuk pulang. Ia panik dan tidak punya dokumen apa pun. Sikap paling tepat adalah ....", opts:[{t:"Menyuruhnya mengurus sendiri ke KBRI tanpa panduan", s:2},{t:"Menolak membantu karena tidak ada dokumen pendukung", s:1},{t:"Menenangkannya, menjelaskan prosedur SPLP, dan membantu verifikasi identitasnya via database", s:5},{t:"Memberi surat pengganti tanpa verifikasi identitas", s:4},{t:"Memintanya menunggu sampai keluarganya mengirim dokumen", s:3}], ex:"WNI yang kesulitan di luar negeri dibantu prosedural dengan verifikasi identitas; kepanikan direspons dengan ketenangan."},
{id:"TKP-1943", q:"Seorang warga mengirimkan foto selfie KTP-nya ke kolom komentar media sosial dinas untuk menanyakan status bantuan. Tindakan paling tepat sebagai admin adalah ....", opts:[{t:"Menjawab status bantuannya di kolom komentar", s:2},{t:"Mengabaikan komentarnya", s:3},{t:"Menghapus komentar berisi data pribadi, menghubunginya via DM, dan mengedukasi agar tidak mengumbar data pribadi", s:5},{t:"Menyukai komentarnya agar ia merasa diperhatikan", s:1},{t:"Menjawab via DM tanpa menghapus komentarnya", s:4}], ex:"Data pribadi yang terumbar diamankan segera (hapus) plus edukasi; menjawab di publik justru memperparah paparan."},
{id:"TKP-1944", q:"Anda bertugas di bagian perizinan. Seorang warga membawa berkas lengkap tetapi fotokopinya buram dan tidak terbaca. Sikap paling tepat adalah ....", opts:[{t:"Menolak berkasnya dan menyuruhnya fotokopi ulang di luar", s:2},{t:"Menerima berkas buram apa adanya", s:1},{t:"Mengarahkan ke fasilitas fotokopi/scan di kantor atau membantu memindai ulang dokumen aslinya", s:5},{t:"Meneruskannya ke atasan tanpa solusi", s:3},{t:"Memintanya kembali besok dengan fotokopi yang jelas", s:4}], ex:"Fasilitas pendukung di kantor menghilangkan alasan bolak-balik warga untuk masalah sepele seperti fotokopi."},
{id:"TKP-1945", q:"Warga bernama Dewi melaporkan bahwa namanya dicoret dari daftar penerima PKH tanpa pemberitahuan. Ia merasa masih layak menerima. Sikap paling tepat adalah ....", opts:[{t:"Menjelaskan pencoretan sudah sesuai data pusat tanpa bisa diganggu gugat", s:2},{t:"Menyuruhnya menerima keputusan dengan lapang dada", s:1},{t:"Mengecek alasan pencoretan, menjelaskan dasarnya, dan memandu mekanisme sanggah atau pendataan ulang", s:5},{t:"Berjanji mengembalikan namanya tanpa verifikasi", s:4},{t:"Memintanya melapor ke pusat langsung", s:3}], ex:"Setiap pencoretan bansos harus bisa dijelaskan dasarnya dan ada jalur sanggah; warga berhak tahu alasannya."},
{id:"TKP-1946", q:"Anda melihat antrean loket layanan didominasi calo yang menawarkan jasa percepatan ke warga. Tindakan paling tepat adalah ....", opts:[{t:"Membiarkannya karena calo membantu warga yang terburu-buru", s:1},{t:"Mengusir calo tanpa memperbaiki sistem antrean", s:2},{t:"Menertibkan area loket, memperkuat verifikasi identitas antrean, dan mengedukasi warga agar tidak memakai calo", s:5},{t:"Melarang warga berbicara dengan calo", s:4},{t:"Melaporkan ke satpam dan selesai", s:3}], ex:"Pemberantasan calo butuh penertiban fisik, penguatan sistem, dan edukasi warga secara bersamaan."},
{id:"TKP-1947", q:"Seorang warga bernama Fajar komplain via email bahwa petugas loket merokok di ruang pelayanan ber-AC. Sikap paling tepat menindaklanjuti adalah ....", opts:[{t:"Mengabaikan karena merokok adalah hak pribadi", s:1},{t:"Menegur petugas di depan warga lain agar jera", s:2},{t:"Memverifikasi, menegur dan membina petugas, serta menegakkan kawasan tanpa rokok di area pelayanan", s:5},{t:"Meminta petugas meminta maaf tanpa pembinaan", s:3},{t:"Menegur lisan tanpa penegakan aturan kawasan", s:4}], ex:"Ruang pelayanan wajib bebas rokok; pelanggaran ditindak dengan pembinaan dan penegakan aturan yang konsisten."},
{id:"TKP-1948", q:"Anda petugas data. Seorang peneliti universitas meminta data agregat kependudukan (jumlah per kelompok usia) untuk riset. Sikap paling tepat adalah ....", opts:[{t:"Menolak karena semua data kependudukan rahasia", s:2},{t:"Memberikan data per individu agar risetnya akurat", s:1},{t:"Memberikan data agregat yang tidak mengidentifikasi individu sesuai prosedur permohonan data", s:5},{t:"Memintanya mencari data sendiri di internet", s:3},{t:"Memberikan data agregat tanpa prosedur resmi", s:4}], ex:"Data agregat non-identifikasional boleh dibuka untuk riset lewat prosedur resmi; data individu tetap dilindungi."},
{id:"TKP-1949", q:"Warga bernama Ratna panik karena sertifikat vaksin anaknya tidak muncul di aplikasi padahal sudah imunisasi lengkap. Pendaftaran sekolah butuh bukti itu. Sikap paling tepat adalah ....", opts:[{t:"Menyuruhnya imunisasi ulang agar datanya tercatat", s:1},{t:"Menyuruhnya menunggu sinkronisasi tanpa batas waktu", s:2},{t:"Mengecek data imunisasi di sistem, menerbitkan surat keterangan manual sementara, dan mengawal sinkronisasi datanya", s:5},{t:"Memberi surat keterangan tanpa mengecek data", s:4},{t:"Mengarahkannya ke puskesmas tanpa bantuan", s:3}], ex:"Verifikasi data plus surat keterangan sementara menyelamatkan kebutuhan mendesak warga saat sistem digital bermasalah."},
{id:"TKP-1950", q:"Anda ditugaskan melayani di mobil layanan keliling dukcapil di desa terpencil. Warga membludak melebihi kapasitas formulir yang dibawa. Sikap paling tepat adalah ....", opts:[{t:"Melayani seadanya formulir lalu pulang tanpa kabar", s:2},{t:"Menolak warga yang tidak kebagian dan menyuruh ke kota", s:1},{t:"Mendata semua yang belum terlayani, memberi kepastian jadwal kunjungan ulang, dan mengoordinasikan tambahan logistik", s:5},{t:"Berjanji kembali tanpa jadwal pasti", s:4},{t:"Memprioritaskan warga yang datang paling awal saja", s:3}], ex:"Kepastian jadwal kunjungan ulang mengubah kekecewaan menjadi kepercayaan; layanan keliling harus akuntabel."},
{id:"TKP-1951", q:"Di meja pelayanan perizinan, Anda menerima berkas permohonan izin reklame dari warga bernama Budi. Saat verifikasi lapangan, ternyata papan reklamenya sudah terpasang duluan tanpa izin. Sikap paling tepat adalah ....", opts:[{t:"Menyetujui izinnya karena papan sudah terlanjur terpasang", s:2},{t:"Menerbitkan izin tanpa sanksi agar ia tidak kapok mengurus", s:1},{t:"Menjelaskan pelanggaran pemasangan tanpa izin, memproses izin sesuai aturan termasuk sanksi administratif yang berlaku", s:5},{t:"Menolak izinnya sebagai hukuman", s:3},{t:"Memproses izin sambil mengabaikan pelanggaran yang sudah terjadi", s:4}], ex:"Penegakan aturan tetap adil: pelanggaran ditindak sesuai sanksi, hak mengurus izin tetap dilayani prosedural."},
{id:"TKP-1952", q:"Beredar video di media sosial yang menuduh petugas puskesmas Anda menolak pasien miskin. Video dipotong dan tidak utuh. Langkah paling tepat adalah ....", opts:[{t:"Menuntut pengunggah video atas pencemaran nama baik", s:1},{t:"Mengabaikan karena video jelas hasil editan", s:2},{t:"Mengumpulkan kronologi utuh, menerbitkan klarifikasi berbasis fakta, dan membuka dialog dengan pengunggah", s:5},{t:"Membantah singkat tanpa bukti kronologi", s:4},{t:"Meminta platform menghapus video tanpa klarifikasi", s:3}], ex:"Video potongan dilawan dengan kronologi utuh yang faktual; dialog terbuka lebih meyakinkan daripada ancaman hukum."},
{id:"TKP-1953", q:"Seorang warga bernama Siti datang ke kecamatan dengan anak kembar yang masih bayi untuk mengurus akta kelahiran. Berkasnya kurang fotokopi KK. Sikap paling tepat adalah ....", opts:[{t:"Menyuruhnya pulang fotokopi dulu dan antre ulang", s:1},{t:"Menolak melayani karena berkas tidak lengkap", s:2},{t:"Membantu memfotokopi di kantor, memproses akta, dan memprioritaskannya sebagai ibu membawa bayi", s:5},{t:"Memproses tanpa fotokopi KK", s:4},{t:"Memintanya kembali besok dengan berkas lengkap", s:3}], ex:"Bantuan fotokopi di tempat plus prioritas kelompok rentan menghilangkan hambatan sepele bagi warga."},
{id:"TKP-1954", q:"Anda menerima laporan bahwa oknum petugas meminta warga mengisi formulir kepuasan dengan identitas palsu agar skor naik. Tindak lanjut paling tepat adalah ....", opts:[{t:"Membiarkannya karena skor kepuasan memang ditargetkan tinggi", s:1},{t:"Menegur oknum di depan umum agar jera", s:2},{t:"Menginvestigasi, menindak oknum, membatalkan data survei yang tercemar, dan memperbaiki mekanisme survei", s:5},{t:"Melaporkan ke atasan tanpa investigasi mandiri", s:3},{t:"Menegur oknum tanpa membatalkan data yang tercemar", s:4}], ex:"Manipulasi survei adalah fraud data; diinvestigasi, ditindak, dan data tercemar dibatalkan agar evaluasi jujur."},
{id:"TKP-1955", q:"Warga bernama Agus ingin melaporkan jalan rusak via aplikasi, tetapi aplikasinya meminta izin akses kontak dan galeri yang tidak relevan. Ia bertanya ke helpdesk. Respon paling tepat adalah ....", opts:[{t:"Menyuruhnya memberikan semua izin agar aplikasi jalan", s:1},{t:"Menjelaskan aplikasi memang butuh banyak izin", s:2},{t:"Menjelaskan prinsip minimisasi data, meneruskan ke tim teknis untuk perbaikan izin, dan memberi alternatif lapor via kanal lain", s:5},{t:"Menyarankannya tidak usah melapor via aplikasi", s:3},{t:"Menjelaskan tanpa meneruskan ke tim teknis", s:4}], ex:"Aplikasi layanan hanya boleh meminta data yang relevan; masukan warga diteruskan untuk perbaikan nyata."},
{id:"TKP-1956", q:"Anda petugas loket di kantor pajak. Seorang wajib pajak lansia bernama Slamet tidak paham e-filing dan hampir menangis karena takut didenda. Sikap paling tepat adalah ....", opts:[{t:"Menyuruhnya membayar denda saja karena memang kewajibannya", s:1},{t:"Menjelaskan e-filing rumit dan menyuruhnya minta tolong anaknya", s:2},{t:"Mendampinginya mengisi e-filing hingga terkirim, menjelaskan tenggat, dan memastikan ia terhindar dari denda", s:5},{t:"Mengisikan e-filing untuknya tanpa penjelasan", s:4},{t:"Mengarahkannya ke konsultan pajak berbayar", s:3}], ex:"Pendampingan hingga tuntas plus edukasi tenggat melindungi lansia dari denda yang sebenarnya bisa dihindari."},
{id:"TKP-1957", q:"Seorang warga difabel daksa bernama Hendra kesulitan menjangkau tombol mesin antrean yang terlalu tinggi. Ia mengadu ke Anda. Tindak lanjut paling tepat adalah ....", opts:[{t:"Menyarankannya selalu membawa pendamping", s:2},{t:"Menjelaskan mesin memang standar pabrik dan tidak bisa diubah", s:3},{t:"Mengusulkan penyesuaian tinggi mesin atau tombol bantuan ke pimpinan, serta menugaskan petugas membantu sementara", s:5},{t:"Mengabaikan karena hanya satu pengadu", s:1},{t:"Menugaskan petugas membantu tanpa mengusulkan perbaikan", s:4}], ex:"Aduan aksesibilitas fisik ditindaklanjuti ke perbaikan fasilitas dengan solusi pendampingan sementara."},
{id:"TKP-1958", q:"Anda menemukan rekan kerja menggunakan data nomor ponsel warga dari database untuk menawarkan dagangannya via WhatsApp. Tindakan paling tepat adalah ....", opts:[{t:"Membiarkannya karena hanya menawarkan dagangan, tidak merugikan", s:2},{t:"Ikut meminta nomor untuk keperluan serupa", s:1},{t:"Menegur rekan, mengingatkannya soal penyalahgunaan data pribadi, dan melaporkannya bila berlanjut", s:5},{t:"Melaporkannya langsung tanpa menegur", s:3},{t:"Mengingatkannya sekali tanpa tindak lanjut", s:4}], ex:"Menggunakan data warga untuk kepentingan pribadi adalah penyalahgunaan wewenang; ditegur lalu dilaporkan bila berlanjut."},
{id:"TKP-1959", q:"Warga bernama Dewi mengeluh via WhatsApp resmi bahwa surat domisilinya salah ketik nama jalan. Ia butuh yang benar untuk wawancara kerja siang ini. Respon paling tepat adalah ....", opts:[{t:"Menyuruhnya datang dan antre seperti biasa tanpa prioritas", s:2},{t:"Mengatakan tidak bisa karena surat sudah diterbitkan", s:1},{t:"Memverifikasi kesalahannya, menerbitkan perbaikan segera, dan mengirimkan versi digital yang bisa dicetak", s:5},{t:"Berjanji memperbaiki besok", s:3},{t:"Memperbaiki tanpa verifikasi kesalahan", s:4}], ex:"Kesalahan instansi diperbaiki segera dengan solusi digital; kebutuhan mendesak warga direspons proporsional."},
{id:"TKP-1960", q:"Anda koordinator posko pengaduan banjir. Banyak warga melapor rumahnya terendam, tetapi tim verifikasi terbatas. Strategi paling tepat adalah ....", opts:[{t:"Melayani yang melapor paling keras agar tidak ribut", s:1},{t:"Menunda semua verifikasi sampai tim lengkap", s:2},{t:"Membuat prioritas berbasis tingkat keparahan, melibatkan relawan terlatih, dan transparan soal antrean verifikasi", s:5},{t:"Memverifikasi seadanya tanpa prioritas", s:4},{t:"Meminta warga memverifikasi sendiri dengan foto", s:3}], ex:"Prioritas berbasis keparahan plus pelibatan relawan dan transparansi antrean adalah manajemen darurat yang adil."},
{id:"TKP-1961", q:"Seorang warga bernama Putri ingin mengurus paspor untuk bekerja ke luar negeri, tetapi namanya berbeda satu huruf antara KTP dan ijazah. Sikap paling tepat adalah ....", opts:[{t:"Menolak dan menyuruhnya memperbaiki sendiri tanpa panduan", s:2},{t:"Memproses dengan data yang ada agar ia cepat berangkat", s:1},{t:"Menjelaskan dokumen mana yang jadi acuan, memandu penetapan pengadilan bila perlu, dan memberi kepastian alur", s:5},{t:"Meneruskannya ke atasan tanpa penjelasan", s:3},{t:"Memberi daftar syarat tanpa menjelaskan alur perbaikannya", s:4}], ex:"Perbedaan nama antar-dokumen diselesaikan lewat alur hukum yang jelas; warga dipandu, bukan dilepas sendiri."},
{id:"TKP-1962", q:"Akun media sosial dinas Anda dibanjiri komentar warga yang kecewa soal distribusi bantuan yang dinilai tidak merata. Respon paling tepat adalah ....", opts:[{t:"Menonaktifkan kolom komentar agar kritik berhenti", s:1},{t:"Menghapus komentar-komentar negatif", s:2},{t:"Menjawab dengan data distribusi yang transparan, mengakui kekurangan bila ada, dan menjelaskan perbaikan yang dilakukan", s:5},{t:"Membalas bahwa semua sudah sesuai prosedur tanpa data", s:3},{t:"Berjanji memperbaiki tanpa menjelaskan data dan rencana", s:4}], ex:"Kritik massal dijawab dengan data terbuka dan pengakuan jujur; menutup komentar justru memicu ketidakpercayaan."},
{id:"TKP-1963", q:"Warga bernama Joko datang ke dukcapil membawa surat keterangan lahir dari dukun beranak, bukan dari bidan atau rumah sakit. Ia ingin membuat akta kelahiran anaknya. Sikap paling tepat adalah ....", opts:[{t:"Menolak karena surat dari dukun tidak sah", s:1},{t:"Menerima surat itu apa adanya tanpa verifikasi", s:2},{t:"Menjelaskan syarat surat keterangan lahir resmi, membantu verifikasi lewat saksi dan RT/RW, serta memproses sesuai ketentuan", s:5},{t:"Menyuruhnya mencari bidan yang mau menerbitkan surat", s:3},{t:"Memproses tanpa syarat tambahan agar cepat", s:4}], ex:"Hak anak atas akta kelahiran dilindungi; verifikasi alternatif lewat saksi memastikan keabsahan tanpa mempersulit."},
{id:"TKP-1964", q:"Anda petugas di bagian informasi. Seorang warga bertanya soal prosedur yang sebenarnya bukan wewenang dinas Anda. Sikap paling tepat adalah ....", opts:[{t:"Menjawab sekenanya agar ia tidak kecewa", s:2},{t:"Menyuruhnya pergi ke dinas lain tanpa penjelasan", s:1},{t:"Menjelaskan bukan wewenang Anda, memberi tahu dinas yang tepat beserta alamat dan kontaknya", s:5},{t:"Menjelaskan bukan wewenang Anda tanpa rujukan", s:3},{t:"Meneruskannya ke atasan agar atasan menjawab", s:4}], ex:"Merujuk warga ke instansi yang tepat dengan info kontak lengkap adalah pelayanan prima lintas instansi."},
{id:"TKP-1965", q:"Seorang lansia bernama Ratna ingin mencairkan bantuan tetapi tidak bisa tanda tangan karena tangannya tremor. Petugas menolak mencairkan. Sebagai pengawas, tindakan paling tepat adalah ....", opts:[{t:"Mendukung penolakan petugas demi keamanan administrasi", s:2},{t:"Menyuruhnya pulang dan kembali dengan cap jempol bermeterai", s:3},{t:"Mengizinkan verifikasi alternatif sesuai SOP (cap jempol disaksikan) dengan pendampingan penuh", s:5},{t:"Mencairkan tanpa verifikasi apa pun karena kasihan", s:1},{t:"Meminta petugas mencairkan diam-diam tanpa prosedur", s:4}], ex:"SOP verifikasi alternatif (cap jempol bersaksi) melindungi hak lansia tanpa mengorbankan akuntabilitas."},
{id:"TKP-1966", q:"Anda menemukan unggahan warga yang memuji pelayanan dinas Anda secara berlebihan dan terindikasi dibuat oleh buzzer bayaran. Sikap paling tepat adalah ....", opts:[{t:"Membagikan ulang pujian itu untuk citra dinas", s:1},{t:"Mengabaikannya karena toh isinya positif", s:2},{t:"Tidak ikut menyebarkan, fokus pada peningkatan layanan nyata, dan membangun kepercayaan lewat kinerja", s:5},{t:"Menghapus unggahan pujian itu", s:3},{t:"Mengucapkan terima kasih resmi atas pujian tersebut", s:4}], ex:"Citra institusi dibangun dari kinerja nyata, bukan pujian rekayasa; integritas komunikasi publik harus dijaga."},
{id:"TKP-1967", q:"Warga bernama Andi melaporkan bahwa tetangganya membuang sampah ke selokan hingga banjir. Ia meminta identitasnya dirahasiakan karena takut bermusuhan. Sikap paling tepat adalah ....", opts:[{t:"Menolak laporan tanpa identitas jelas", s:2},{t:"Memberitahu identitas pelapor ke tetangganya agar selesai kekeluargaan", s:1},{t:"Menerima laporan, merahasiakan identitas pelapor, dan menindaklanjuti via penertiban resmi", s:5},{t:"Menyuruhnya menegur tetangganya sendiri", s:3},{t:"Mencatat laporan tanpa tindak lanjut", s:4}], ex:"Kerahasiaan pelapor dijamin agar warga berani melapor; penertiban dilakukan lewat mekanisme resmi."},
{id:"TKP-1968", q:"Anda petugas call center. Seorang warga menelepon untuk menanyakan hal yang sama berulang-ulang karena tidak paham penjelasan Anda. Sikap paling tepat adalah ....", opts:[{t:"Menutup telepon karena ia membuang waktu", s:1},{t:"Menjawab dengan nada kesal agar ia sadar", s:2},{t:"Tetap sabar, menyederhanakan bahasa, memberi contoh konkret, dan memastikan ia paham sebelum menutup", s:5},{t:"Menyuruhnya membaca website sendiri", s:3},{t:"Mengulangi penjelasan yang sama persis dengan cepat", s:4}], ex:"Kesabaran dan adaptasi bahasa hingga penelepon paham adalah standar emas layanan call center publik."},
{id:"TKP-1969", q:"Seorang warga bernama Maya ingin mengajukan gugatan sengketa informasi karena permohonannya ditolak dinas Anda. Ia meminta salinan surat penolakan resmi. Sikap paling tepat adalah ....", opts:[{t:"Menolak memberikan salinan agar ia tidak bisa menggugat", s:1},{t:"Mempersulit dengan alasan arsip tidak ditemukan", s:2},{t:"Memberikan salinan penolakan resmi dan menjelaskan hak serta tata cara sengketa informasinya", s:5},{t:"Memberikan salinan tanpa menjelaskan haknya", s:4},{t:"Meneruskannya ke atasan tanpa kepastian", s:3}], ex:"Hak warga menggugat sengketa informasi dihormati; transparansi justru menunjukkan kedewasaan institusi."},
{id:"TKP-1970", q:"Anda bertugas di loket pelayanan. Seorang warga bernama Dedi membawa berkas dalam map lusuh dan berpakaian kumal. Petugas sebelah berbisik menyuruh Anda melayaninya seadanya. Sikap paling tepat adalah ....", opts:[{t:"Melayaninya seadanya sesuai saran rekan", s:2},{t:"Memintanya antre di loket lain", s:1},{t:"Melayaninya dengan ramah dan standar yang sama seperti warga lain, mengabaikan bisikan rekan", s:5},{t:"Melayaninya dengan baik tetapi menegur rekan di depan warga", s:4},{t:"Melaporkannya ke atasan tanpa menegur langsung", s:3}], ex:"Pelayanan publik tidak diskriminatif; penampilan warga tidak boleh memengaruhi standar layanan."},
{id:"TKP-1971", q:"Warga bernama Fajar melaporkan via aplikasi bahwa tiang listrik miring membahayakan anak-anak sekolah. Statusnya belum ditindaklanjuti seminggu. Tindak lanjut paling tepat adalah ....", opts:[{t:"Menjelaskan perbaikan tiang butuh waktu lama tanpa kepastian", s:3},{t:"Mengabaikan karena wewenang perusahaan listrik", s:2},{t:"Mengoordinasikan segera dengan pemilik aset karena menyangkut keselamatan, dan mengabari pelapor", s:5},{t:"Meneruskan tanpa memantau dan mengabari", s:4},{t:"Menyuruh warga melapor langsung ke perusahaan listrik", s:1}], ex:"Laporan yang menyangkut keselamatan diprioritaskan dan dikoordinasikan lintas pihak dengan kabar ke pelapor."},
{id:"TKP-1972", q:"Anda menemukan data warga di komputer kantor tidak dilindungi kata sandi dan bisa diakses siapa saja yang lewat. Tindakan paling tepat adalah ....", opts:[{t:"Membiarkannya karena semua pegawai kantor orang baik", s:1},{t:"Menggunakannya untuk mempercepat pekerjaan Anda", s:2},{t:"Mengamankan dengan kata sandi, membatasi akses sesuai kebutuhan, dan mengusulkan kebijakan keamanan data", s:5},{t:"Memberi tahu rekan agar berhati-hati tanpa mengamankan", s:4},{t:"Melaporkan ke atasan tanpa tindakan pengamanan awal", s:3}], ex:"Pengamanan data dimulai dari hal dasar (kata sandi, batas akses) plus usulan kebijakan agar sistemik."},
{id:"TKP-1973", q:"Seorang ibu bernama Nur ingin mendaftarkan anaknya ke PAUD negeri, tetapi kuotanya penuh dan ia tidak mampu membayar swasta. Sikap paling tepat adalah ....", opts:[{t:"Menyuruhnya menunggu tahun depan", s:2},{t:"Menolak karena kuota memang sudah penuh", s:1},{t:"Mengecek kemungkinan penambahan kuota atau alternatif PAUD terdekat, dan memasukkannya ke daftar tunggu prioritas", s:5},{t:"Menjelaskan kuota penuh tanpa alternatif", s:3},{t:"Berjanji memasukkan anaknya tanpa kepastian", s:4}], ex:"Mencari alternatif nyata plus daftar tunggu prioritas menunjukkan keberpihakan pada akses pendidikan anak."},
{id:"TKP-1974", q:"Anda petugas di dinas sosial. Seorang warga mengaku kehilangan KTP dan meminta surat keterangan untuk mencairkan bantuan hari ini juga. Sikap paling tepat adalah ....", opts:[{t:"Mencairkan bantuan tanpa verifikasi karena mendesak", s:1},{t:"Menolak mentah-mentah tanpa solusi", s:2},{t:"Memverifikasi identitasnya via database, menerbitkan surat keterangan sementara, dan memandu pengurusan KTP baru", s:5},{t:"Menyuruhnya mengurus KTP baru dulu baru kembali", s:3},{t:"Memberi surat keterangan tanpa verifikasi database", s:4}], ex:"Verifikasi database memungkinkan solusi sementara yang sah; warga terbantu tanpa prosedur dilanggar."},
{id:"TKP-1975", q:"Warga bernama Budi mengadu bahwa petugas parkir liar memungut biaya di halaman kantor dinas Anda. Tindak lanjut paling tepat adalah ....", opts:[{t:"Mengabaikan karena parkir bukan urusan dinas", s:2},{t:"Menyuruh warga tidak usah membayar tanpa penertiban", s:3},{t:"Mengoordinasikan penertiban area kantor, memasang tarif resmi, dan memastikan warga tidak dipungli", s:5},{t:"Menegur juru parkir tanpa penertiban sistemik", s:4},{t:"Menyalahkan warga yang mau membayar", s:1}], ex:"Area kantor adalah tanggung jawab institusi; penertiban sistemik plus tarif resmi melindungi warga dari pungli."},
{id:"TKP-1976", q:"Anda admin media sosial kelurahan. Seorang warga berkomentar menanyakan jadwal siskamling dengan menyebut nama jalan dan nomor rumahnya lengkap. Tindakan paling tepat adalah ....", opts:[{t:"Menjawab jadwalnya di kolom komentar", s:2},{t:"Mengabaikan komentarnya", s:3},{t:"Menghapus detail alamatnya, menjawab via DM, dan mengedukasi agar tidak mengumbar alamat di publik", s:5},{t:"Menyukai komentarnya sebagai apresiasi", s:1},{t:"Menjawab via DM tanpa menghapus komentarnya", s:4}], ex:"Alamat warga yang terumbar diamankan segera plus edukasi privasi; keamanan warga adalah prioritas."},
{id:"TKP-1977", q:"Seorang warga bernama Rina ingin mengurus surat keterangan waris, tetapi ada ahli waris yang tidak setuju pembagiannya. Ia meminta Anda memihaknya. Sikap paling tepat adalah ....", opts:[{t:"Memihaknya karena ia yang datang mengurus", s:1},{t:"Menolak mengurus karena ada sengketa", s:2},{t:"Menjelaskan posisi netral, memproses sesuai dokumen sah, dan mengarahkan sengketa ke musyawarah atau pengadilan", s:5},{t:"Meneruskannya ke lurah tanpa penjelasan", s:3},{t:"Memproses sesuai keinginannya diam-diam", s:4}], ex:"Petugas netral dan prosedural; sengketa waris diselesaikan lewat musyawarah atau hukum, bukan keberpihakan."},
{id:"TKP-1978", q:"Anda petugas di puskesmas. Seorang pasien bernama Joko menolak dirujuk ke RSUD karena takut biaya, padahal kondisinya butuh penanganan lanjutan. Sikap paling tepat adalah ....", opts:[{t:"Membiarkannya pulang karena itu haknya", s:2},{t:"Memaksanya dirujuk tanpa penjelasan", s:1},{t:"Menjelaskan urgensi rujukan, skema pembiayaan (BPJS/keringanan), dan mendampinginya hingga proses rujukan jelas", s:5},{t:"Menjelaskan urgensi tanpa membahas biaya", s:4},{t:"Menyuruhnya memikirkan sendiri dan kembali bila berubah pikiran", s:3}], ex:"Ketakutan biaya diatasi dengan penjelasan skema pembiayaan; edukasi urgensi medis menyelamatkan nyawa."},
{id:"TKP-1979", q:"Warga bernama Dewi menemukan kesalahan nama di data kependudukan digitalnya setelah menikah dan ganti nama. Ia butuh perbaikan untuk urusan bank. Sikap paling tepat adalah ....", opts:[{t:"Menyuruhnya menggunakan nama lama saja di bank", s:1},{t:"Menolak karena perubahan nama butuh proses pengadilan yang lama", s:2},{t:"Memverifikasi dokumen pendukung, memproses pembaruan data, dan memberi surat keterangan sementara untuk bank", s:5},{t:"Memproses tanpa verifikasi dokumen", s:4},{t:"Mengarahkannya ke pengadilan tanpa penjelasan rinci", s:3}], ex:"Pembaruan data pasca-pernikahan diproses verifikatif dengan solusi sementara untuk kebutuhan mendesak."},
{id:"TKP-1980", q:"Anda melihat warga lanjut usia kebingungan di depan papan informasi digital yang hanya berupa layar sentuh. Sikap paling tepat adalah ....", opts:[{t:"Membiarkannya karena papan digital memang untuk yang melek teknologi", s:1},{t:"Menyuruhnya bertanya ke satpam", s:2},{t:"Menghampirinya, membantu mencari informasi yang dibutuhkan, dan mengusulkan papan info cetak pendamping", s:5},{t:"Membantu sekali tanpa mengusulkan perbaikan", s:4},{t:"Menjelaskan cara memakai layar sentuh dengan cepat", s:3}], ex:"Inisiatif membantu plus usulan media pendamping memastikan informasi publik aksesibel bagi semua usia."},
{id:"TKP-1981", q:"Seorang warga mengirimkan tangkapan layar percakapan yang menunjukkan oknum petugas dinas Anda meminta imbalan. Ia takut melapor resmi. Sikap paling tepat adalah ....", opts:[{t:"Mengabaikan karena buktinya hanya tangkapan layar", s:2},{t:"Menyebarkan tangkapan layar ke grup kantor", s:1},{t:"Menerima laporan dengan jaminan kerahasiaan, memverifikasi, dan memproses sesuai mekanisme disiplin", s:5},{t:"Meminta ia melapor terbuka agar diproses", s:3},{t:"Menasihatinya menghapus bukti demi keamanan", s:4}], ex:"Bukti awal ditindaklanjuti dengan perlindungan pelapor; verifikasi menentukan langkah disiplin berikutnya."},
{id:"TKP-1982", q:"Anda petugas arsip digital. Permintaan salinan dokumen warga menumpuk karena Anda satu-satunya yang bisa mengoperasikan sistem. Sikap paling tepat adalah ....", opts:[{t:"Mengerjakan pelan-pelan sesuai kemampuan tanpa melapor", s:3},{t:"Menolak permintaan baru sampai tumpukan habis", s:2},{t:"Melaporkan bottleneck ke atasan, mengusulkan pelatihan rekan, dan memprioritaskan berdasarkan urgensi", s:5},{t:"Menyalahkan sistem yang rumit", s:1},{t:"Lembur diam-diam tanpa melaporkan masalah struktural", s:4}], ex:"Bottleneck dilaporkan dengan solusi (pelatihan, prioritas) agar layanan tidak bergantung pada satu orang."},
{id:"TKP-1983", q:"Warga bernama Agus ingin membayar retribusi pasar via aplikasi, tetapi saldo terpotong namun status tetap belum bayar. Ia takut ditagih lagi. Respon paling tepat adalah ....", opts:[{t:"Menyuruhnya membayar lagi dan mengurus refund belakangan", s:1},{t:"Menjelaskan itu kesalahan sistem tanpa solusi", s:2},{t:"Memverifikasi transaksinya, menerbitkan bukti bayar resmi, dan mengoordinasikan perbaikan status dengan pengelola aplikasi", s:5},{t:"Memberi bukti bayar manual tanpa verifikasi", s:4},{t:"Memintanya menunggu perbaikan sistem tanpa kepastian", s:3}], ex:"Verifikasi transaksi plus bukti resmi melindungi warga dari tagihan ganda; perbaikan status dikoordinasikan."},
{id:"TKP-1984", q:"Anda ditugaskan sosialisasi bahaya hoaks ke warga desa. Peserta banyak yang tidak bisa baca tulis. Metode paling tepat adalah ....", opts:[{t:"Membagikan leaflet dan berharap ada yang membacakan", s:2},{t:"Membatalkan sosialisasi karena peserta tidak bisa baca", s:1},{t:"Menggunakan metode lisan-visual (cerita, peragaan, video sederhana) dengan bahasa sehari-hari", s:5},{t:"Menyampaikan materi standar apa adanya", s:3},{t:"Meminta perangkat desa yang menyampaikan ulang", s:4}], ex:"Edukasi disesuaikan dengan kemampuan audiens; metode visual-lisan memastikan pesan anti-hoaks tersampaikan."},
{id:"TKP-1985", q:"Seorang warga bernama Putri melapor bahwa bantuan untuknya dialihkan ke orang lain oleh oknum dengan alasan ia sudah mampu. Ia keberatan karena masih membutuhkan. Sikap paling tepat adalah ....", opts:[{t:"Membenarkan pengalihan karena keputusan sudah dibuat", s:2},{t:"Mengembalikan bantuannya tanpa verifikasi", s:1},{t:"Memverifikasi ulang kelayakannya lewat pendataan faktual, dan mengoreksi bila terbukti masih layak", s:5},{t:"Menyuruhnya menerima keputusan dengan ikhlas", s:4},{t:"Meneruskan ke atasan tanpa verifikasi", s:3}], ex:"Pengalihan bantuan harus berbasis verifikasi kelayakan faktual, bukan penilaian sepihak oknum."},
{id:"TKP-1986", q:"Anda petugas loket di Samsat. Seorang warga bernama Hendra tidak bisa menunjukkan BPKB asli karena masih di leasing. Sikap paling tepat adalah ....", opts:[{t:"Menolak mentah-mentah tanpa alternatif", s:2},{t:"Memproses tanpa BPKB demi target layanan", s:1},{t:"Menjelaskan syarat surat keterangan leasing sebagai pengganti sah dan memandu pengurusannya", s:5},{t:"Meneruskannya ke atasan tanpa penjelasan", s:3},{t:"Memintanya kembali setelah BPKB lunas", s:4}], ex:"Surat keterangan leasing adalah pengganti sah BPKB; warga dipandu, bukan ditolak mentah."},
{id:"TKP-1987", q:"Warga bernama Siti mengunggah foto antrean loket Anda yang sepi dengan caption memuji, padahal foto itu diambil sebelum jam buka. Sikap paling tepat sebagai humas adalah ....", opts:[{t:"Membagikan ulang foto itu untuk pencitraan", s:1},{t:"Mengabaikannya karena isinya positif", s:2},{t:"Tidak ikut menyebarkan informasi yang menyesatkan dan tetap fokus pada perbaikan layanan nyata", s:5},{t:"Menghapus unggahan warga itu", s:3},{t:"Mengucapkan terima kasih resmi atas unggahannya", s:4}], ex:"Informasi menyesatkan tidak disebarkan meski menguntungkan citra; kepercayaan dibangun dari fakta."},
{id:"TKP-1988", q:"Anda menerima pesan WhatsApp dari warga yang mengaku melihat petugas dinas Anda menerima uang di warung kopi. Ia tidak berani menyebut nama. Tindak lanjut paling tepat adalah ....", opts:[{t:"Mengabaikan karena laporannya tidak jelas", s:2},{t:"Menuduh semua petugas yang suka ke warung kopi", s:1},{t:"Menampung informasi, menjamin kerahasiaan, dan menindaklanjuti lewat pengawasan internal", s:5},{t:"Meminta warga menyebut nama atau laporannya dibuang", s:3},{t:"Menyebarkan info itu ke grup kantor agar pelakunya waspada", s:4}], ex:"Laporan anonim soal integritas ditampung dan ditindaklanjuti via pengawasan internal dengan pelapor dilindungi."},
{id:"TKP-1989", q:"Seorang ibu hamil bernama Maya datang ke puskesmas untuk kontrol, tetapi buku KIA-nya tertinggal di rumah. Petugas menolak memeriksa. Sebagai pengawas, tindakan paling tepat adalah ....", opts:[{t:"Mendukung penolakan demi ketertiban administrasi", s:2},{t:"Menyuruhnya pulang mengambil buku KIA", s:1},{t:"Mengizinkan pemeriksaan dengan mencatat di sistem, dan mengingatkannya membawa buku KIA berikutnya", s:5},{t:"Memeriksanya tanpa pencatatan apa pun", s:4},{t:"Meminta petugas memeriksa diam-diam tanpa prosedur", s:3}], ex:"Pelayanan kesehatan ibu hamil tidak boleh tertunda karena administrasi; pencatatan sistem menjaga ketertiban."},
{id:"TKP-1990", q:"Anda mengelola website layanan dinas. Seorang warga mengeluh formulir online-nya hilang setelah dikirim dan tidak ada bukti terkirim. Perbaikan paling tepat adalah ....", opts:[{t:"Menyarankannya mengisi ulang sampai berhasil", s:2},{t:"Menjelaskan sistem memang kadang begitu", s:1},{t:"Menambahkan notifikasi bukti terkirim (nomor tiket), riwayat pengajuan, dan memperbaiki keandalan sistem", s:5},{t:"Memberi nomor tiket manual tanpa perbaikan sistem", s:4},{t:"Memintanya datang langsung ke kantor saja", s:3}], ex:"Bukti terkirim dan riwayat pengajuan adalah kepastian layanan digital; keandalan sistem diperbaiki, bukan dinormalisasi."},
{id:"TKP-1991", q:"Warga bernama Dedi ingin mengurus surat keterangan tidak mampu untuk beasiswa anaknya, tetapi ia gengsi mengaku miskin di depan tetangganya yang jadi perangkat RT. Sikap paling tepat adalah ....", opts:[{t:"Menyuruhnya mengatasi gengsinya sendiri", s:2},{t:"Membocorkan keperluannya ke RT agar cepat diproses", s:1},{t:"Menjamin kerahasiaan keperluannya, memproses sesuai verifikasi faktual, dan melayani dengan empati", s:5},{t:"Memproses tanpa verifikasi agar ia tidak malu", s:4},{t:"Menyarankannya mengurus di kelurahan lain", s:3}], ex:"Kerahasiaan dan empati menghilangkan hambatan psikologis warga miskin mengakses haknya."},
{id:"TKP-1992", q:"Anda petugas di dinas kependudukan. Seorang WNI keturunan bertanya apakah ia dipersulit karena sukunya. Data menunjukkan berkasnya memang kurang. Sikap paling tepat adalah ....", opts:[{t:"Tersinggung dan menuduhnya rasis", s:1},{t:"Menjelaskan syarat yang kurang secara rinci dan transparan, memastikan ia paham tidak ada diskriminasi", s:5},{t:"Memprosesnya dengan prioritas agar tidak dituduh diskriminatif", s:2},{t:"Menjelaskan syarat tanpa menyinggung isu diskriminasi", s:4},{t:"Meneruskannya ke atasan agar tidak salah bicara", s:3}], ex:"Transparansi syarat yang rinci adalah jawaban terbaik atas dugaan diskriminasi; pelayanan setara untuk semua."},
{id:"TKP-1993", q:"Seorang warga bernama Ratna melaporkan via WhatsApp resmi bahwa ia menerima surat tilang palsu yang mengatasnamakan dinas perhubungan. Respon paling tepat adalah ....", opts:[{t:"Menyuruhnya membayar saja agar tidak bermasalah", s:1},{t:"Menjelaskan itu bukan wewenang Anda", s:2},{t:"Mengonfirmasi ciri surat tilang resmi, menegaskan itu penipuan, dan membantunya melapor ke pihak berwajib", s:5},{t:"Menjelaskan itu penipuan tanpa membantu melapor", s:4},{t:"Memintanya mengabaikan tanpa verifikasi", s:3}], ex:"Edukasi ciri dokumen resmi plus pendampingan lapor melindungi warga dari penipuan yang mencatut institusi."},
{id:"TKP-1994", q:"Anda koordinator layanan. Seorang petugas berprestasi meminta dispensasi jam kerja karena harus merawat orang tua yang sakit. Sikap paling tepat adalah ....", opts:[{t:"Menolak karena aturan jam kerja sama untuk semua", s:2},{t:"Memberinya dispensasi penuh tanpa pengaturan agar ia senang", s:1},{t:"Mencarikan skema fleksibel (tukar shift/cuti) yang tidak mengganggu layanan dan tetap manusiawi", s:5},{t:"Menyuruhnya cuti tanpa gaji saja", s:3},{t:"Memberi dispensasi lisan tanpa pencatatan", s:4}], ex:"Fleksibilitas yang terstruktur menyeimbangkan empati pada pegawai dengan keberlangsungan layanan publik."},
{id:"TKP-1995", q:"Warga bernama Joko ingin melihat langsung proses verifikasi berkas izinnya karena curiga ada permainan. Ia meminta didampingi. Sikap paling tepat adalah ....", opts:[{t:"Menolak karena proses verifikasi bersifat internal", s:2},{t:"Mengizinkannya mengawasi penuh setiap tahapan", s:1},{t:"Menjelaskan tahapan verifikasi secara transparan dan memberinya akses memantau status via sistem tracking", s:5},{t:"Berjanji tidak ada permainan tanpa penjelasan", s:4},{t:"Menyuruhnya percaya saja pada petugas", s:3}], ex:"Transparansi proses lewat penjelasan tahapan dan tracking status menjawab kecurigaan dengan fakta."},
{id:"TKP-1996", q:"Anda menemukan tumpukan berkas pengajuan warga yang belum diproses selama dua bulan di lemari rekan yang sedang cuti panjang. Tindakan paling tepat adalah ....", opts:[{t:"Membiarkannya menunggu rekan kembali dari cuti", s:2},{t:"Membuang berkas lama agar tidak menumpuk", s:1},{t:"Mengoordinasikan pengambilalihan pemrosesan, menghubungi warga yang terdampak, dan meminta maaf atas keterlambatan", s:5},{t:"Memproses diam-diam tanpa memberitahu warga", s:4},{t:"Melaporkan ke atasan tanpa mengambil alih", s:3}], ex:"Berkas terbengkalai diambil alih segera dengan komunikasi ke warga; pembiaran adalah maladministrasi."},
{id:"TKP-1997", q:"Seorang warga difabel netra bernama Fajar ingin memberikan penilaian kepuasan layanan via mesin survei layar sentuh yang tidak aksesibel. Sikap paling tepat adalah ....", opts:[{t:"Menyuruhnya meminta tolong warga lain mengisi", s:2},{t:"Mengabaikan karena survei tidak wajib", s:1},{t:"Membantunya menyampaikan penilaian via alternatif aksesibel dan mengusulkan survei yang ramah disabilitas", s:5},{t:"Mengisikan penilaian untuknya tanpa bertanya", s:4},{t:"Menjelaskan mesin memang belum aksesibel tanpa solusi", s:3}], ex:"Suara penyandang disabilitas dalam evaluasi layanan sama berharganya; alternatif aksesibel disediakan plus usulan perbaikan."},
{id:"TKP-1998", q:"Warga bernama Dewi mengadu bahwa namanya dipakai orang untuk mengajukan pinjaman online dengan KTP yang ia unggah ke aplikasi layanan Anda tahun lalu. Sikap paling tepat adalah ....", opts:[{t:"Menyalahkan Dewi karena ceroboh mengunggah KTP", s:1},{t:"Menjelaskan aplikasi sudah aman dan menyuruhnya melapor ke polisi sendiri", s:2},{t:"Membantu menelusuri riwayat akses datanya, mengamankan akunnya, dan mendampinginya melapor ke aparat", s:5},{t:"Menyarankan mengganti KTP tanpa investigasi", s:4},{t:"Memintanya menunggu investigasi internal tanpa pendampingan", s:3}], ex:"Dugaan kebocoran dari sistem instansi ditelusuri serius; korban didampingi, bukan disalahkan."},
{id:"TKP-1999", q:"Anda petugas di loket kelurahan. Jam pelayanan hampir tutup, tetapi masih ada lima warga antre termasuk seorang ibu hamil. Sikap paling tepat adalah ....", opts:[{t:"Menutup loket tepat waktu dan menyuruh mereka kembali besok", s:1},{t:"Melayani seadanya dengan terburu-buru", s:2},{t:"Menyelesaikan semua antrean yang sudah ada, memprioritaskan ibu hamil, dengan tetap ramah", s:5},{t:"Melayani tiga orang pertama dan sisanya disuruh kembali", s:3},{t:"Menyelesaikan antrean tetapi dengan wajah kesal", s:4}], ex:"Warga yang sudah antre sebelum tutup wajib diselesaikan; keramahan hingga akhir adalah etos pelayanan prima."},
{id:"TKP-2000", q:"Seorang warga bernama Budi menulis ulasan di media sosial memuji kecepatan layanan digital dinas Anda, tetapi menyebut ada bug kecil di formulir alamat. Respon paling tepat sebagai pengelola adalah ....", opts:[{t:"Mengabaikan karena ulasannya sudah positif", s:2},{t:"Membayarnya agar menghapus bagian tentang bug", s:1},{t:"Menyampaikan terima kasih, menindaklanjuti perbaikan bug, dan mengabari warga itu setelah diperbaiki", s:5},{t:"Berterima kasih tanpa menindaklanjuti bug-nya", s:4},{t:"Menjelaskan bug itu hal wajar tanpa perbaikan", s:3}], ex:"Masukan bug dari warga yang puas sekalipun ditindaklanjuti; menutup loop umpan balik membangun loyalitas publik."}
];
